  function trackTimer(timer) { state.timers.add(timer); return timer; }
  function clearTracked(timer) { clearInterval(timer); clearTimeout(timer); state.timers.delete(timer); }
  function clearTimers() { [...state.timers].forEach(clearTracked); }
  const TOAST_VISIBLE_LIMIT=3;
  let combatFeedbackTimer=null;
  function removeToastNode(node){if(!node)return;if(node._toastTimer)clearTracked(node._toastTimer);node.remove();}
  function scheduleToastRemoval(node,duration){if(node._toastTimer)clearTracked(node._toastTimer);node._toastTimer=trackTimer(setTimeout(()=>{node.remove();state.timers.delete(node._toastTimer);node._toastTimer=null;},duration));}
  function transientInputRoute(message){
    if(/^当前状态不可攻击$|米内没有可攻击目标$|^视野内没有可锁定目标$/.test(message))return{kind:'miss',control:'attack',icon:'攻',title:'没有可攻击目标'};
    if(/^当前状态不可施法$|^主动槽为空$|^主动冷却中|^\d+(?:\.\d+)?米内没有可见合法目标|^50米内没有可见合法单位|^3米内放置点被地形阻挡/.test(message))return{kind:'miss',control:'active',icon:'技',title:'施法未提交'};
    if(/^当前状态不可交互$|^附近没有可交互对象$/.test(message))return{kind:'miss',control:'interact',icon:'互',title:'附近没有交互对象'};
    return null;
  }
  function toast(message, duration = 2300, kind = '', options = {}) {
    const transient=state.ui.screen==='battle'&&transientInputRoute(String(message));if(transient){setMotionState(transient.icon,transient.title,String(message),'cast');combatInputFeedback(transient.kind,transient.control);return null;}
    const region=$('#toast-region');if(!region)return null;
    const key=String(options.key||`${kind}:${message}`),existing=[...region.children].find(node=>node.dataset.toastKey===key);
    if(existing){scheduleToastRemoval(existing,duration);return existing;}
    while(region.children.length>=TOAST_VISIBLE_LIMIT)removeToastNode(region.firstElementChild);
    const node=document.createElement('div');node.className=`toast${kind?` ${kind}`:''}`;node.dataset.toastKey=key;node.textContent=message;region.append(node);scheduleToastRemoval(node,duration);return node;
  }
  function combatInputFeedback(kind='miss',control='attack'){
    const nodes=[$('#aim-reticle'),$(`.mobile-inputs .${control}`)].filter(Boolean),classes=['input-feedback-miss','input-feedback-blocked','input-feedback-lock'];
    nodes.forEach(node=>node.classList.remove(...classes));
    if(combatFeedbackTimer)clearTracked(combatFeedbackTimer);
    const cssClass=`input-feedback-${kind}`;nodes.forEach(node=>{void node.offsetWidth;node.classList.add(cssClass);});
    combatFeedbackTimer=trackTimer(setTimeout(()=>{nodes.forEach(node=>node.classList.remove(cssClass));state.timers.delete(combatFeedbackTimer);combatFeedbackTimer=null;},260));
  }
