  function terrainBiomeDetails(w){const spacing=22,minX=Math.floor((state.sim.player.x-CAMERA_WIDTH_M/2)/spacing)*spacing,maxX=state.sim.player.x+CAMERA_WIDTH_M/2,minY=Math.floor((state.sim.player.y-CAMERA_HEIGHT_M/2)/spacing)*spacing,maxY=state.sim.player.y+CAMERA_HEIGHT_M/2,nodes=[];for(let x=minX;x<=maxX;x+=spacing)for(let y=minY;y<=maxY;y+=spacing){const region=w.regions.find(r=>pointInPolygon({x,y},r.polygon));if(!region)continue;const p=cameraPercent({x,y}),seed=stableRoll(`biome:${x}:${y}`),ox=(seed%13)-6,oy=((seed>>4)%13)-6,cx=p.x*12.8+ox,cy=p.y*7.2+oy;if(region.id==='REGION_BURNING_WATER')nodes.push(`<g data-terrain-semantic="water-current" transform="translate(${cx} ${cy}) rotate(${seed%45-22})"><path class="terrain-water-flow broad" d="M-34 2C-20-10-7 12 7 0S25-7 36 2"/><path class="terrain-water-glint" d="M-22 8C-10 2 1 11 14 5"/></g>`);else if(region.id==='REGION_DRAGON_RIDGE'&&seed%2===0)nodes.push(`<g data-terrain-semantic="rock-outcrop" transform="translate(${cx} ${cy}) rotate(${seed%28-14})"><path class="terrain-rock-outcrop" d="M-23 11Q-16-7-7-6Q-2-22 8-14Q18-12 25 10Z"/><path class="terrain-cliff-line" d="M-14 5Q-4-8 2-4T16 2"/></g>`);else if(region.id==='REGION_SPIDER_GORGE'&&seed%5===0)nodes.push(`<g data-terrain-semantic="subtle-web" class="terrain-web" transform="translate(${cx} ${cy})"><circle r="12"/><path d="M-13 0H13M0-13V13M-9-9L9 9M9-9L-9 9"/></g>`);else if(region.id==='REGION_LOST_SOUL_FIELD')nodes.push(`<g data-terrain-semantic="wind-grass"><path class="terrain-field-line" d="M${cx-30} ${cy-6}Q${cx-10} ${cy-13} ${cx+5} ${cy-7}T${cx+31} ${cy-9}"/><path class="terrain-grass-tuft" d="M${cx} ${cy+7}q-7-12-9-16M${cx} ${cy+7}q2-13 7-18M${cx} ${cy+7}q9-9 13-10"/></g>`);else if(region.id==='REGION_CENTIPEDE_CITY'&&seed%2===0)nodes.push(`<path data-terrain-semantic="weathered-stone" class="terrain-city-tile" d="M${cx-15} ${cy-8}Q${cx} ${cy-11} ${cx+16} ${cy-7}L${cx+13} ${cy+8}Q${cx} ${cy+11} ${cx-16} ${cy+7}Z"/>`);else if(region.id==='REGION_BROKEN_GOLD'&&seed%2===0)nodes.push(`<path data-terrain-semantic="earth-crack" class="terrain-earth-crack" d="M${cx-20} ${cy-8}L${cx-6} ${cy-2}L${cx-1} ${cy+12}M${cx-6} ${cy-2}L${cx+12} ${cy-7}L${cx+22} ${cy+2}"/>`);}return`<g class="terrain-biome-details">${nodes.join('')}</g>`;}
