  function runTenMatchAudit(){return TEN_MATCH_CHECKS.map((round,roundIndex)=>({round:roundIndex+1,title:round.title,scene:round.scene,items:round.checks.split('|').map((issue,index)=>({id:`R${String(roundIndex+1).padStart(2,'0')}-${String(index+1).padStart(2,'0')}`,issue,evidence:`${round.title.split(' · ')[1]} · ${index<5?'真源字段/出生快照':index<10?'交互状态/权威校验':index<15?'HUD与世界实体':index<19?'并发失败路径':'断线与恢复路径'}`,status:'已补齐并进入回归'}))}));}
  function openTenMatchAudit(round=state.ui.auditRound||0){const runs=state.sim.auditRuns?.length?state.sim.auditRuns:runTenMatchAudit(),safe=clamp(Number(round)||0,0,runs.length-1),current=runs[safe];state.ui.auditRound=safe;openWorldSheet('10局递进审计 · 每局独立20项',current.title,`<div class="audit-overview"><b>${current.scene}</b><span>本局 ${current.items.length} 项 · 十局共 ${runs.reduce((sum,x)=>sum+x.items.length,0)} 项 · 无重复ID</span></div><div class="audit-round-tabs">${runs.map((x,i)=>`<button class="${i===safe?'active':''}" data-action="audit-round" data-round="${i}">${i+1}</button>`).join('')}</div><div class="audit-list">${current.items.map(x=>`<article><i>✓</i><span><b>${x.id} · ${esc(x.issue)}</b><small>${esc(x.evidence)}</small></span><em>${x.status}</em></article>`).join('')}</div><div class="world-sheet-actions"><button class="btn ghost" data-action="close-world-sheet">返回战场</button></div>`,{type:'service',mode:'service',kind:'audit'});}

  function renderWorldState(){
    const m=state.match;if(!m)return;const boss=$('#boss-target'),warning=$('#world-warning');
    if(m.worldEvent?.kind==='boss'){
      boss.hidden=false;$('#boss-name').textContent=m.worldEvent.name;$('#boss-hp').style.width=`${m.worldEvent.hp}%`;$('#boss-state').textContent=m.worldEvent.state;
    }else boss.hidden=true;
    if(m.warning){warning.hidden=false;$('#warning-title').textContent=m.warning.title;$('#warning-copy').textContent=m.warning.copy;}else warning.hidden=true;
    renderTargetFrame();
  }
  function renderTargetFrame(){const m=state.match,frame=$('#target-frame'),actor=selectedSimActor(),pve=!actor&&state.pve.entities.find(x=>x.instanceId===state.sim.pveTargetId&&pveTargetable(x)),target=actor||pve,detail=$('[data-action="inspect-combat-target"]',frame);if(actor&&(!inCamera(actor)||surfaceDistanceMeters(actor,state.sim.player)>32||!hasDirectLineOfSight(actor))||pve&&(!inCamera(pve)||surfaceDistanceMeters(pve,state.sim.player)>39||!pveHasDirectLos(pve))){state.sim.targetId=null;state.sim.pveTargetId=null;m.targetLock=0;frame.hidden=true;return;}if(!m||m.targetLock<=0||!target||actor?.state==='dead'||pve?.hp<=0){frame.hidden=true;return;}if(actor){m.enemyHp=actor.hp;m.enemyLevel=actor.level;m.enemyLives=actor.lives;$('#target-frame-avatar').src=heroArt(actor.hero,'avatar-512.png');detail.dataset.kind='player';detail.dataset.id=actor.id;}else{m.enemyHp=clamp(pve.hp/pve.maxHp*100,0,100);$('#target-frame-avatar').src=monsterVisualArt(pve.visual);detail.dataset.kind='pve';detail.dataset.id=pve.instanceId;}const dz=(target.z||0)-(state.sim.player.z||0),heightCopy=Math.abs(dz)>=2?`${dz>0?'↑':'↓'} 高差${Math.abs(dz)}m`:'同层',range=surfaceDistanceMeters(target,state.sim.player),centerRange=worldDistanceMeters(target,state.sim.player);frame.hidden=false;frame.dataset.elevation=Math.abs(dz)>=2?(dz>0?'up':'down'):'same';frame.dataset.targetKind=actor?'player':'pve';frame.dataset.surfaceDistanceM=range.toFixed(3);frame.dataset.centerDistanceM=centerRange.toFixed(3);$('#target-frame-hp').style.width=`${m.enemyHp}%`;$('#target-frame-name').textContent=actor?`${actor.hero.英雄} · Lv.${actor.level}`:`${targetDisplayName(pve)} · ${monsterTierLabel(pve.monster)}`;$('#target-frame-range').textContent=`表面 ${range.toFixed(1)}m · ${heightCopy}`;$('#target-frame-state').textContent=actor?`${actor.hero.五行} · ${actorPublicState(actor)} · 私有构筑与AI目标不公开`:`${monsterElementLabel(pve.monster.element||pve.visual?.element)} · ${pveStateCopy(currentPveState(pve))[1]} · 生命${Math.ceil(pve.hp)}/${pve.maxHp}`;$('#target-frame-lock').textContent=`${m.targetLock.toFixed(0)}s`;}
  function inspectWorldTarget(kind='player'){
    if(kind==='monster')return openWorldSheet('怪物可见状态 · Q-01—Q-15','金肥猪 · Lv.2',`<section class="target-profile"><img src="../assets/monsters/runtime/MVS_023/portrait.webp" alt="金肥猪"><div><h3>金肥猪 · 金系肥猪怪</h3><p>近战 · 战斗状态可见 · 私有随机结果不可见</p></div></section><div class="interaction-facts"><span><b>生命 68%</b><small>当前可见比例</small></span><span><b>警戒</b><small>发现玩家 · 正在前摇</small></span><span><b>近战</b><small>冲锋危险区</small></span></div><div class="visible-status-list"><span><i>!</i><b>肥猪冲锋</b><small>0.6秒前摇</small></span><span><i>巢</i><b>死胡同停驻</b><small>回到袋底后保持当前坐标，死亡才按规则重生</small></span></div><div class="interaction-warning">使用正式怪物原画，不复用英雄形象。怪物技能只显示已进入公开前摇或当前状态的部分；每项掉落独立判定，未触发机制和未来结果不会提前泄露。</div>`,{type:'target',mode:'target'});
    if(kind==='boss')return openWorldSheet('公共首领状态 · H-14/Q-04—Q-15','核心首领 · 镜世妖核',`<section class="target-profile"><img src="../assets/summon/CORE_MIRROR/portrait.png" alt="镜世妖核"><div><h3>镜世妖核 · 核心Boss</h3><p>公开目标 · ${state.match.worldEvent?.state||'尚未进入公共阶段'}</p></div></section><div class="interaction-facts"><span><b>${state.match.worldEvent?.hp??100}%</b><small>公共生命</small></span><span><b>三庭</b><small>权威tick迁场</small></span><span><b>公开掉落</b><small>无末击拾取保护</small></span></div><div class="visible-status-list"><span><i>镜</i><b>镜面折射</b><small>危险区公开前摇</small></span><span><i>移</i><b>迁场阶段</b><small>落地无敌公开显示</small></span><span><i>真</i><b>核心真视</b><small>10米 · 墙体仍阻挡</small></span></div><div class="interaction-warning">六种签名机制分别使用方向、范围、命中和低闪反馈；这里只显示当前已公开机制，不显示未来随机顺序。</div>`,{type:'target',mode:'target'});
    const m=state.match,actor=selectedSimActor(),hero=actor?.hero||state.maps.hero.get('H002'),name=hero?.英雄||'红孩儿',hp=actor?.hp??m.enemyHp,lives=actor?.lives??m.enemyLives,range=actor?surfaceDistanceMeters(actor,state.sim.player):12,publicState=actor?actorPublicState(actor):'战斗中',cast=actor?.lastCast||'尚未观察到公开施法',dz=actor?(actor.z||0)-(state.sim.player.z||0):0,heightCopy=Math.abs(dz)>=2?`${dz>0?'↑':'↓'} 高差${Math.abs(dz)}米`:'同层';openWorldSheet('目标公开信息',`${name} · 敌方玩家`,`<section class="target-profile"><img src="${heroArt(hero,'avatar-512.png')}" alt="${esc(name)}"><div><h3>${esc(name)} · Lv.${actor?.level||m.enemyLevel}</h3><p>${esc(hero?.五行||'火')} · 生命 ${Math.ceil(hp)}% · 剩余命数 ${lives}</p></div></section><div class="interaction-facts"><span><b>表面 ${range.toFixed(1)}米</b><small>${heightCopy} · 有直视</small></span><span><b>${m.targetLock?`锁定 ${m.targetLock}s`:'未锁定'}</b><small>穿墙/隐身会解除</small></span><span><b>${actor?.state==='revive'?'复活保护':'可战斗'}</b><small>${esc(publicState)}</small></span></div><div class="visible-status-list"><span><i>${esc((hero?.五行||'火').slice(0,1))}</i><b>五行：${esc(hero?.五行||'火')}</b><small>克制关系公开</small></span><span><i>${SIM_STATE_COPY[actor?.state]?.[0]||'战'}</i><b>${esc(publicState)}</b><small>仅显示可观察动作与控制状态</small></span><span><i>技</i><b>${esc(cast)}</b><small>只记录已发生的公开释放表现</small></span></div><div class="interaction-warning danger"><b>对手私有构筑不可查看；AI意图同样不公开</b><br>四个被动、三件装备、手牌、冷却、未释放主动、寻路目标、拾取目标和交易目标均不公开；战场只显示可观察动作、受控、施法前摇、复活保护和已释放技能。</div>`,{type:'target',mode:'target'});
  }
  function inspectSelf(){let m=state.match;if(!m?.selected){ensureBattle();m=state.match;}if(!m?.selected)return toast('本人状态尚未载入');const statuses=[m.protection&&{id:'protection',icon:'护',copy:`复活保护 ${m.protection}秒`},m.shield&&{id:'shield',icon:'盾',copy:`护盾 ${m.shield}`},m.pvpAge<3&&{id:'combat',icon:'战',copy:`脱离PVP还需 ${3-m.pvpAge}秒`},m.effects?.seer&&{id:'seer',icon:'眼',copy:`千里眼符 ${m.effects.seer}秒`},m.effects?.mirror&&{id:'mirror',icon:'鉴',copy:`照妖镜 ${m.effects.mirror}秒`}].filter(Boolean);openWorldSheet('本人权威状态 · H-01/H-12/H-24',`${m.selected.英雄} · Lv.${m.level}`,`<section class="target-profile"><img src="${heroArt(m.selected,'avatar-512.png')}" alt="${esc(m.selected.英雄)}"><div><h3>${m.selected.五行} · ${m.selected.模板}</h3><p>生命 ${Math.ceil(m.hp)}/${m.maxHp} · 护盾 ${m.shield} · 剩余 ${m.lives} 命</p></div></section><div class="interaction-facts"><span><b>${m.status}</b><small>生命状态</small></span><span><b>${m.gold}金 / ${m.gems}宝石</b><small>本局资源</small></span><span><b>${m.level>=15?'已满级':`${m.xp}/${xpThreshold(m.level)}`}</b><small>升级经验</small></span><span><b>${m.pvpAge>=3?'已脱战':`${m.pvpAge}秒`}</b><small>PVP计时</small></span></div><div class="visible-status-list">${statuses.length?statuses.map(x=>`<button type="button" data-action="inspect-status" data-status="${x.id}"><i>${x.icon}</i><b>${x.copy}</b><small>点击查看来源与解除条件</small></button>`).join(''):'<span><i>净</i><b>当前无临时状态</b><small>装备、被动与主动仍在下方构筑栏管理</small></span>'}</div><div class="world-sheet-actions"><button class="btn secondary" data-action="toggle-build">查看并管理本人构筑</button><button class="btn ghost" data-action="close-world-sheet">返回战场</button></div>`,{type:'target',mode:'target',kind:'self'});}
  function inspectStatus(id){const m=state.match;if(!m)return;let data={protection:['复活保护',`${m.protection}秒`,'来源：真死后的权威复活。免疫伤害；任何进攻或世界交互输入会先解除保护，再重新校验该次请求。'],shield:['当前护盾',`${m.shield}点`,'来源与剩余量公开显示；实际伤害先消耗护盾。护盾受损属于真实伤害，会中断换装和交易。'],combat:['PVP脱战计时',`${Math.max(0,3-m.pvpAge)}秒`,'最近受到或造成玩家实际伤害后开始；普通商店需脱战3秒，太白需脱战5秒。怪物与天劫伤害不重置该计时。'],seer:['千里眼符',`${m.effects.seer}秒`,'45米内探测合法商店标记；不揭露隐身目标，墙体仍阻挡。计时结束立即回收新增信息。'],mirror:['照妖镜',`${m.effects.mirror}秒`,'20米内揭露目标位置；伏石不能阻挡，但墙体仍阻挡锁定。显形不等于穿墙可攻击。'],'p10-dormant':['P10黑山特效休眠','黑山已关闭','12:30后黑山专属概率改写不再可触发；装备自身最大生命属性与出售价值继续保留，未被删除。']}[id];const active=String(id||'').replace(/^active-runtime-/,'');const record=(state.sim.activeRuntime||[]).find(x=>x.id===active);const effect=(state.sim.activeEffects||[]).find(x=>x.id===String(id||'').replace(/^active-effect-/,''));if(!data&&record)data=[record.name||record.skillId,`${Math.max(0,record.expiresAt-(m.elapsed||0)).toFixed(1)}秒`, `主动运行时状态：${record.kind||'临时效果'}。到期后自动回收并恢复基础值。`];if(!data&&effect)data=[effect.name,`${Math.max(0,effect.expiresAt-(m.elapsed||0)).toFixed(1)}秒`,`持续区域：${effect.type||'STATUS'}。范围、tick与到期均由权威运行时账本驱动。`];if(!data)return;openWorldSheet('状态详情 · H-12/H-24',data[0],`<div class="status-detail-card"><i>${id==='protection'?'护':id==='shield'?'盾':id==='combat'?'战':id==='seer'?'眼':id==='mirror'?'鉴':record?.kind==='HEAL'?'疗':record?.kind==='SHIELD'?'盾':effect?'域':'效'}</i><div><b>${data[1]}</b><p>${data[2]}</p></div></div><div class="interaction-facts"><span><b>权威计时</b><small>客户端只表现</small></span><span><b>来源明确</b><small>不与装备描述冲突</small></span><span><b>即时回收</b><small>失效不留残影</small></span></div><div class="world-sheet-actions"><button class="btn ghost" data-action="close-world-sheet">关闭详情</button></div>`,{type:'target',mode:'compact',kind:'status'});}
  function showWarning(title,copy,duration=3200){if(!state.match)return;state.match.warning={title,copy,lowFlash:state.settings.lowFlash,assetId:`${String(title).replace(/\W+/g,'_')}${state.settings.lowFlash?'_LOWFLASH':''}`};uiSound('warning');renderWorldState();trackTimer(setTimeout(()=>{if(state.match){state.match.warning=null;renderWorldState();}},duration));}
  function showBoss(stateName='ACTIVE_COURT'){
    ensureBattle();const labels={ACTIVE_COURT:['核心首领 · 镜世妖核','万劫三庭 · 公开目标',76],MIGRATION_WARNING:['核心首领 · 镜世妖核','15秒后迁往下一庭',42],DEAD_TIMER:['核心首领 · 镜世妖核','已被击败 · 复活倒计时',0],FINAL_ACTIVE:['核心首领 · 镜世妖核','灭世阶段 · 最终现身',100]};const v=labels[stateName]||labels.ACTIVE_COURT;state.match.worldEvent={kind:'boss',name:v[0],state:v[1],hp:v[2]};emitUIEvent(UI_EVENT_TYPES.BOSS_TELEGRAPH,{stateName,name:v[0],state:v[1],hp:v[2]});renderWorldState();showWarning(stateName==='MIGRATION_WARNING'?'首领即将迁场':'核心首领现身',v[1]);
  }

  function lineOfSightBetween(from,target){return exactWallLos(from,target,state.worldSource);}
  function hasDirectLineOfSight(target){if(target?.monster?.tier==='PIG'&&target.den&&pointInsidePigDenCorridor(state.sim.player,target.den)&&pointInsidePigDenCorridor(target,target.den))return true;const smoke=state.sim.activeEffects?.find(x=>x.skillId==='H038'&&x.expiresAt>(state.match?.elapsed||0));if(smoke){const insideTarget=worldDistanceMeters(target,smoke)<=smoke.radius,insidePlayer=worldDistanceMeters(state.sim.player,smoke)<=smoke.radius;if(insideTarget&&!insidePlayer&&!(equipmentHas('P9')&&worldDistanceMeters(target,state.sim.player)<=20))return false;}return lineOfSightBetween(state.sim.player,target);}
  function basicAttackRange(){const base=Number(String(state.match?.selected?.['射程/攻速']||'5m').match(/(\d+(?:\.\d+)?)m/)?.[1])||5;return base+(equipmentHas('P17')?0.7:0)+(equipmentHas('G10')?3:0);}
  function basicAttackPeriodMs(){const raw=String(state.match?.selected?.['射程/攻速']||''),rate=Number(raw.match(/\/\s*(\d+(?:\.\d+)?)\s*s(?:⁻¹|-1)?/)?.[1]||raw.match(/攻速\s*[=:：]?\s*(\d+(?:\.\d+)?)/)?.[1]||1.6),mult=Math.max(.1,Number(state.match?.attackSpeedMultiplier)||1);return clamp(Math.round(1000/(rate*mult)),120,5000);}
  function activeSpec(item){const geometry=String(item?.瞄准与几何||''),read=key=>Number(geometry.match(new RegExp(`${key}=(\\d+(?:\\.\\d+)?)m`))?.[1])||0,readSeconds=key=>Number(geometry.match(new RegExp(`${key}=(\\d+(?:\\.\\d+)?)s`))?.[1])||0;return{geometry,target:geometry.match(/target=([^；]+)/)?.[1]||'DIRECTION',shape:geometry.match(/shape=([^；]+)/)?.[1]||'NONE',cast:geometry.match(/cast=([^；]+)/)?.[1]||'INSTANT',range:read('range'),radius:read('radius'),width:read('width'),duration:readSeconds('duration')};}
  function legalCombatTarget(maxRange,aimWorld=null){const candidates=(state.sim.actors||[]).filter(actor=>actor.state!=='dead'&&actor.state!=='revive'&&inCamera(actor)&&equipmentTargetVisible(actor,maxRange));const selected=selectedSimActor();if(selected&&candidates.includes(selected)&&(!aimWorld||Math.max(0,worldDistanceMeters(selected,aimWorld)-entityCollisionRadius(selected))<=Math.max(3,maxRange*.12)))return selected;if(aimWorld)return candidates.sort((a,b)=>Math.max(0,worldDistanceMeters(a,aimWorld)-entityCollisionRadius(a))-Math.max(0,worldDistanceMeters(b,aimWorld)-entityCollisionRadius(b)))[0]||null;return candidates.sort((a,b)=>surfaceDistanceMeters(a,state.sim.player)-surfaceDistanceMeters(b,state.sim.player))[0]||null;}
  function pointInsidePigDenCorridor(point,den){if(!den)return false;const width=Number(den.width||5)/2+.12,segments=[[den.entrance,den.initial],[den.initial,den.end]];return segments.some(([a,b])=>distanceToSegment(point,a,b).distance<=width);}
  function pveHasDirectLos(entity){const hidden=!!(entity?.stealthed||entity?.hidden||entity?.fushiHidden);if(hidden)return equipmentHas('P9')&&worldDistanceMeters(entity,state.sim.player)<=20&&hasDirectLineOfSight(entity);return entity?.monster?.tier==='PIG'&&entity.den&&pointInsidePigDenCorridor(state.sim.player,entity.den)&&pointInsidePigDenCorridor(entity,entity.den)||hasDirectLineOfSight(entity);}
  function legalPveTarget(maxRange,aimWorld=null){const candidates=(state.pve.entities||[]).filter(entity=>pveTargetable(entity)&&inCamera(entity)&&surfaceDistanceMeters(entity,state.sim.player)<=maxRange&&pveHasDirectLos(entity));const selected=candidates.find(x=>x.instanceId===state.sim.pveTargetId);if(selected&&(!aimWorld||Math.max(0,worldDistanceMeters(selected,aimWorld)-entityCollisionRadius(selected))<=Math.max(3,maxRange*.16)))return selected;if(aimWorld)return candidates.sort((a,b)=>Math.max(0,worldDistanceMeters(a,aimWorld)-entityCollisionRadius(a))-Math.max(0,worldDistanceMeters(b,aimWorld)-entityCollisionRadius(b)))[0]||null;return candidates.sort((a,b)=>surfaceDistanceMeters(a,state.sim.player)-surfaceDistanceMeters(b,state.sim.player))[0]||null;}
  function legalAnyTarget(maxRange,aimWorld=null){const player=legalCombatTarget(maxRange,aimWorld),monster=legalPveTarget(maxRange,aimWorld);if(!player)return monster;if(!monster)return player;const anchor=aimWorld||state.sim.player;return worldDistanceMeters(player,anchor)<=worldDistanceMeters(monster,anchor)?player:monster;}
  const isPveTarget=target=>!!target?.monster;
  const isSummonTarget=target=>!!target&&!!state.sim?.summons?.includes(target);
  const combatEntityKey=target=>String(target?.instanceId||target?.id||'');
  const targetDisplayName=target=>isPveTarget(target)?(target.visual?.name||target.monster.name):isSummonTarget(target)?target.name:target?.hero?.英雄;
  function livingCombatEntities({includeSummons=true}={}){return[...state.sim.actors.filter(x=>x.hp>0&&x.state!=='dead'&&x.state!=='revive'),...state.pve.entities.filter(x=>x.hp>0&&x.state!=='dead'&&x.state!=='locked'),...(includeSummons?state.sim.summons.filter(x=>x.hp>0):[])];}
  function entityDestinationLegal(entity,point,{ignore=[]}={}){const radius=entityCollisionRadius(entity)||.46,ignored=new Set([entity,...ignore]),from={x:Number(entity?.x??point.x),y:Number(entity?.y??point.y)};if(!runtimePointIsClear(point,{includeDynamic:true,clearance:radius})||pointInWaterRegion(point)&&!pointOnWalkableCrossing(point))return false;if(Math.abs(terrainHeightAt(point)-terrainHeightAt(from))>4)return false;return!livingCombatEntities().some(other=>!ignored.has(other)&&worldDistanceMeters(other,point)<radius+entityCollisionRadius(other)+.05);}
  function skillTargetKey(target){return isPveTarget(target)?`pve:${target.instanceId}`:isSummonTarget(target)?`summon:${target.id}`:`player:${target.id}`;}
  function resolveSkillTarget(key){const [kind,id]=String(key||'').split(':');return kind==='pve'?state.pve.entities.find(x=>x.instanceId===id):kind==='summon'?state.sim.summons.find(x=>x.id===id):state.sim.actors.find(x=>x.id===id);}
  function d13TypeAllowed(target){if(!target)return false;if(isSummonTarget(target))return target.hp>0&&target.public!==false;if(!isPveTarget(target))return target.state!=='dead'&&target.state!=='revive'&&target.hp>0;return ['ORDINARY_MELEE','ORDINARY_RANGED','FLYING','PIG','DAMAGEABLE_SUMMON'].includes(target.monster?.tier)&&pveTargetable(target);}
  function d13TargetLegal(target){return d13TypeAllowed(target)&&surfaceDistanceMeters(target,state.sim.player)<=50&&hasDirectLineOfSight(target);}
  function d13DestinationLegal(entity,point,ignore=[]){return entityDestinationLegal(entity,point,{ignore});}
  function d13Candidates(){return [...state.sim.actors,...state.pve.entities,...state.sim.summons].filter(d13TargetLegal).sort((a,b)=>surfaceDistanceMeters(a,state.sim.player)-surfaceDistanceMeters(b,state.sim.player)||combatEntityKey(a).localeCompare(combatEntityKey(b)));}
  function cancelD13Selection(reason='已取消换位选择'){const selection=state.ui.skillTargeting;if(selection?.timer)clearTracked(selection.timer);state.ui.skillTargeting=null;if(state.ui.worldContext?.kind==='d13-target')closeWorldSheet(false);toast(`${reason} · 未进入冷却`);renderBuild();}
  function renderD13Selector(){const selection=state.ui.skillTargeting;if(!selection||selection.skillId!=='D13')return;const candidates=d13Candidates(),first=resolveSkillTarget(selection.firstKey),secondPhase=selection.phase==='WAIT_SECOND_TARGET',remaining=secondPhase?Math.max(0,(selection.expiresAt-performance.now())/1000):0;openWorldSheet('换位 · 双目标',secondPhase?'选择目标B':'选择目标A',`<section class="skill-target-instruction"><b>${secondPhase?`目标A：${esc(targetDisplayName(first)||'已失效')} · 还剩 ${remaining.toFixed(1)}秒`:'依次选择两个50米内可见单位'}</b><small>${secondPhase?'目标B不能与A相同；非法目标不会消耗冷却':'首领、龙与核心Boss免疫，不会出现在合法列表'}</small></section><div class="skill-target-list">${candidates.length?candidates.map(target=>{const key=skillTargetKey(target),same=key===selection.firstKey,type=isPveTarget(target)?target.monster.tier:isSummonTarget(target)?'DAMAGEABLE_SUMMON':'PLAYER';return `<button class="skill-target-row${same?' selected':''}" data-action="d13-select-target" data-id="${key}"><span><b>${esc(targetDisplayName(target))}</b><small>${esc(type)} · 表面${surfaceDistanceMeters(target,state.sim.player).toFixed(1)}m</small></span><em>${same?'已选A':secondPhase?'选作B':'选作A'}</em></button>`;}).join(''):'<div class="empty-state"><b>没有合法可见单位</b><small>移动到目标进入视野与50米范围后重试</small></div>'}</div><div class="world-sheet-actions"><button class="btn" data-action="d13-cancel">取消 · 不进入冷却</button></div>`,{type:'target',mode:'target',kind:'d13-target',phase:selection.phase});}
  function beginD13Selection(){if(state.ui.skillTargeting?.skillId==='D13')return renderD13Selector();if(!d13Candidates().length){playVfx('invalid','D13-NO-FIRST',null,{x:state.sim.player.x+6,y:state.sim.player.y});return toast('50米内没有可见合法单位 · 未进入冷却');}state.ui.skillTargeting={skillId:'D13',phase:'WAIT_FIRST_TARGET',firstKey:null,expiresAt:0,timer:null};renderD13Selector();}
  function selectD13Target(key){const selection=state.ui.skillTargeting,target=resolveSkillTarget(key);if(!selection||selection.skillId!=='D13')return;if(!d13TargetLegal(target)){toast('该目标已离开视野、超过50米或已失效 · 继续等待合法目标');return renderD13Selector();}if(selection.phase==='WAIT_FIRST_TARGET'){selection.firstKey=key;selection.phase='WAIT_SECOND_TARGET';selection.expiresAt=performance.now()+3000;selection.timer=trackTimer(setTimeout(()=>cancelD13Selection('目标B选择超时'),3000));renderD13Selector();return;}if(selection.phase!=='WAIT_SECOND_TARGET')return;if(key===selection.firstKey){toast('目标B不能与目标A相同 · 继续等待，未进入冷却');return renderD13Selector();}const first=resolveSkillTarget(selection.firstKey);selection.phase='COMMIT_OR_CANCEL';const a=first&&{x:first.x,y:first.y,z:first.z??terrainHeightAt(first)},b=target&&{x:target.x,y:target.y,z:target.z??terrainHeightAt(target)},legal=!!a&&!!b&&d13TargetLegal(first)&&d13TargetLegal(target)&&d13DestinationLegal(first,b,[target])&&d13DestinationLegal(target,a,[first]);if(!legal){selection.phase='WAIT_SECOND_TARGET';toast('目标或胶囊落点已失效 · 继续等待，未进入冷却');return renderD13Selector();}let committed=false;try{first.x=b.x;first.y=b.y;first.z=terrainHeightAt(first);target.x=a.x;target.y=a.y;target.z=terrainHeightAt(target);committed=d13DestinationLegal(first,first,[target])&&d13DestinationLegal(target,target,[first]);}catch(error){console.error('D13 atomic swap rejected',error);committed=false;}if(!committed){Object.assign(first,a);Object.assign(target,b);selection.phase='WAIT_SECOND_TARGET';activeRuntimeFeedback({ID:'D13',名称:'换位'},'ATOMIC_SWAP_ROLLBACK',{firstKey:selection.firstKey,secondKey:key,cooldownCommitted:false},'HIGH');toast('原子换位提交失败，双方已回滚 · 继续等待，未进入冷却');return renderD13Selector();}if(selection.timer)clearTracked(selection.timer);state.ui.skillTargeting=null;state.match.activeCooldown=Math.round((Number(state.match.active.item['CD(s)'])||62)*(equipmentHas('P6')?.8:1));advanceJourney('combat');if(state.match.protection)state.match.protection=0;breakFushi('敌对主动提交');closeWorldSheet(false);playVfx('point','D13-A',first,a);playVfx('point','D13-B',target,b);activeRuntimeFeedback({ID:'D13',名称:'换位'},'ATOMIC_SWAP_COMMIT',{firstKey:skillTargetKey(first),secondKey:skillTargetKey(target),cooldown:state.match.activeCooldown},'HIGH');announce(`原子换位完成 · ${targetDisplayName(first)} ↔ ${targetDisplayName(target)} · CD ${state.match.activeCooldown}秒`);pushCombatFeed(`换位提交：${targetDisplayName(first)} ↔ ${targetDisplayName(target)}`,'skill');renderBuild();renderWorldPve();renderWorldSummons();updateLiveSimulationUI(false);}
  function d20PlacementPoint(aim){const source=aim||{x:state.sim.player.x+3,y:state.sim.player.y},dx=source.x-state.sim.player.x,dy=source.y-state.sim.player.y,len=Math.hypot(dx,dy)||1,used=Math.min(3,len);return{x:state.sim.player.x+dx/len*used,y:state.sim.player.y+dy/len*used};}
  function d20PointLegal(point){return runtimePointIsClear(point,{includeDynamic:true,clearance:.45})&&!pointInWaterRegion(point)&&!movementBlocked(state.sim.player,point);}
  function placeD20Trap(aim){const m=state.match;if(m.activeCooldown>0)return toast(`主动冷却中 · ${m.activeCooldown}秒`);const point=d20PlacementPoint(aim);if(!d20PointLegal(point))return toast('3米内放置点被地形阻挡 · 未进入冷却');if(state.sim.traps.length>=3){const oldest=[...state.sim.traps].sort((a,b)=>a.sequence-b.sequence)[0];state.sim.traps=state.sim.traps.filter(x=>x.id!==oldest.id);pushCombatFeed(`陷阱上限3个 · 已移除最早实例 ${oldest.id}`,'skill');}const now=performance.now(),trap={id:`TRAP-${++state.sim.trapSeq}`,sequence:state.sim.trapSeq,x:point.x,y:point.y,z:terrainHeightAt(point),hp:250,maxHp:250,state:'ARMING',placedAt:m.elapsed,expiresAt:m.elapsed+90,armedAt:now+500};state.sim.traps.push(trap);m.activeCooldown=Number(m.active.item['CD(s)'])||16;advanceJourney('combat');if(m.protection)m.protection=0;breakFushi('敌对主动提交');closeWorldSheet(false);playVfx('summon','D20-PLACE',trap,trap,null,{shape:'CIRCLE',radius:.75,duration:.5});announce(`陷阱 ${trap.id} 已放置 · 0.5秒后武装 · 250 HP`);renderBuild();renderWorldSkillEntities();}
