  function skillVfxFamily(spec,mechanism=''){if(/type=SPAWN_(?:SUMMON|DECOYS)/.test(mechanism))return'summon';if(spec.shape==='RING_WALL')return'ringwall';if(spec.shape==='LINE_WALL')return'wall';if(spec.shape==='PROJECTILE')return'projectile';if(spec.shape==='CONE')return'cone';if(spec.shape==='CIRCLE')return spec.target==='SELF'?'self-circle':'circle';if(spec.shape==='POINT')return'point';if(spec.shape==='LINE')return'line';if(spec.target==='SELF')return'buff';if(spec.target.includes('VISIBLE'))return'lock';return'line';}
