  function trueDeath(source='player') { const m=state.match;if(!m.alive)return;m.alive=false;m.status='TRUE_DEATH_RESOLVING';const killer=state.sim.actors.find(x=>x.state==='pursue')?.id||'P02';passiveOwnerTrueDeath(killer,source);interruptChannel('发生真死');clearSummons('主人真死',null,'OWNER_TRUE_DEATH_CLEANUP');closeWorldSheet(false);m.lives--;const dropEntries=[...m.hand.filter(Boolean)];m.hand=handSlots().map(()=>null);if(m.lives===0){dropEntries.push(...m.equipment.filter(Boolean));m.equipment=[null,null,null];normalizeHand();}dropEntries.forEach((entry,i)=>spawnWorldLoot('equipment',entry.item,state.sim.player.x+1+(i%3)*1.1,state.sim.player.y+1+Math.floor(i/3)*1.1,'玩家真死公开掉落',dropEntries.length>1?`DEATH-${state.sim.tick}`:null));const dropped=dropEntries.map(x=>x.item.名称);m.activeCooldown=0;renderBuild();renderBattleHUD();const deathCopy=source==='player'?'被敌方玩家击败':source==='monster'?'被野怪击败':source==='storm'?'受到天劫伤害':'受到环境伤害';openModal('命数变化',m.lives?'失去一条命':'三命已尽',`<section class="death-summary"><strong>${m.lives}</strong><span><b>${m.lives?'剩余命数':'已被淘汰'}</b><small>${deathCopy}</small></span></section><div class="notice danger">${dropped.length?`已公开掉落：${esc(dropped.join('、'))}`:'本次没有装备掉落'}</div><div class="channel"><b>${m.lives?'灵魂即将离体':'已被淘汰'}</b><div class="channel-bar"><i style="width:100%;transition:width 1s linear"></i></div></div>`,{type:'death'});trackTimer(setTimeout(()=>m.lives?startSoulFlight():startSpectate(),1000)); }
