  const SHOP_SCHEDULE={LAND_A:[30,210,390,570,750,900],SHOE_A:[45,225,405,585],TAIBAI:[60,240,420,600,780,900],BLACK:[75,255,435,615],LAND_B:[90,270,450,630],SHOE_B:[105,285,465,645]};
