  function activeShop(){return state.shop.instances.get(state.shop.activeInstance);}
  function stableRoll(key){let h=2166136261;for(const c of key){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0)%100;}
  function stableHash32(key){let h=2166136261;for(const c of String(key)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
