      return openWorldSheet('被动赌局 · N-02/N-18','选择输入被动',`<div class="interaction-warning">大赢/平/亏：${blackProbabilityCopy(kind)}。依次为升1级并换未拥有被动、平级换同级、删除输入。</div>${options?`<div class="slot-choice-grid">${options}</div>`:'<div class="interaction-warning danger">当前没有可作为输入的被动。</div>'}<div class="world-sheet-actions"><button class="btn ghost" data-action="open-black">返回黑山</button></div>`,{type:'service',mode:'service',kind:'blackmountain'});
