  function pveDetail(monsterId,visualId=null){let entity=state.pve.entities.find(x=>x.monster.id===monsterId&&(!visualId||x.visual?.assetId===visualId));if(!entity){const monster=state.worldSource?.monsters.find(x=>x.id===monsterId);if(!monster)return;const visual=visualId?(state.monsterVisuals?.items||[]).find(x=>x.assetId===visualId):monsterVisualFor(monster,`DATA-${monsterId}`),maxHp=Number(monster.hp)||100;entity={instanceId:`DATA-${monsterId}-${visual?.assetId||'MECH'}`,monster,visual,x:50,y:50,spawnX:50,spawnY:50,maxHp,hp:maxHp,state:'patrol'};state.pve.entities.push(entity);}inspectPveEntity(entity.instanceId);}
