    entity.hp=0;entity.state='dead';entity.lastState='dead';if(entity.deadAt==null)schedulePveRespawn(entity,state.match?.elapsed||0);syncMatchCurrency();renderBattleHUD();renderWorldPve();renderWorldLoot();
