    if(showReceipt)openWorldSheet(`怪物掉落结算 · ${d.key}`,`${entity.visual?.name||monster.name} 已死亡`,`${monsterDropHtml(monster)}<div class="monster-roll-receipt"><header><b>本次权威结算</b><small>演示种子 ${esc(seed)} · 每一项按真源独立掷骰 · 末击归属 ${esc(creditOwner)}</small></header><div><span><b>${localCredit?`+${d.gold}`:'0'} 金</b><small>${localCredit?'已结算给本人':creditOwner==='WORLD'?'世界击杀不结算':'归远端末击玩家'}</small></span><span><b>${localCredit?`+${d.xp}`:'0'} 经验</b><small>${localCredit?'已结算给本人':'本地不入账'}</small></span>${localCredit?gemOutcome:''}${publicOutcome}</div></div><div class="interaction-warning">技能书、装备和通用主动严格按真源掉落表判定；宝石直接入账，不生成地面实体。</div><div class="world-sheet-actions"><button class="btn primary" data-action="close-world-sheet">查看地面掉落</button><button class="btn secondary" data-action="pve-roster">继续核对其他怪物</button></div>`,{type:'pickup',mode:'service',kind:'monster-drop',instanceId:entity.instanceId});else{const labels=created.map(x=>x.item.名称),creditCopy=localCredit?`${localGoldAward}金/${Number(d.xp)||0}经验`:creditOwner==='WORLD'?'世界击杀0金/0经验':'奖励归远端末击玩家',groundCopy=labels.length?`地面掉落：${labels.join('、')}`:'本次无地面掉落',gemCopy=gemCount?` · +${gemCount}技能宝石已直接入账`:'';pushCombatFeed(`${entity.visual?.name||monster.name} 死亡 · ${creditCopy} · ${groundCopy}${gemCopy}`,'skill');toast(labels.length?`死亡掉落：${labels.join('、')} · 靠近自动交互${gemCopy}`:localCredit?`击杀结算：+${localGoldAward}金 +${Number(d.xp)||0}经验 · 本次无地面掉落${gemCopy}`:`死亡结算：${creditCopy} · 本次无地面掉落`);}
