  function simulateMonsterDrop(instanceId){const entity=state.pve.entities.find(x=>x.instanceId===instanceId);if(!entity)return toast('怪物实例不存在');if(!pveTargetable(entity))return toast(entity.hp<=0?'该实例已结算；等待重生后才能再次击杀':'该实例尚未公开现身');rollMonsterDrop(entity,{showReceipt:true});}

  function inspectBuild(type,index){
    const m=state.match;normalizePassiveLevels();normalizeHand();
    const entry=type==='passive'?m.passives[index]:type==='equipment'?m.equipment[index]:type==='hand'?m.hand[index]:m.active;
    if(!entry)return openWorldSheet('构筑 · H-03—H-05','空槽',`<div class="interaction-warning">通过世界掉落、技能书或商店获取内容。生产状态不会凭空生成物品。</div><div class="world-sheet-actions"><button class="btn ghost" data-action="close-world-sheet">关闭</button></div>`,{type:'build',mode:'compact'});
    const item=entry.item,level=type==='passive'?passiveLevel(entry):0,handRule=handCapacity()>HAND_BASE_CAPACITY?'基础1 + 布袋1':'基础1';let actions='';
    if(type==='passive')actions=`<button class="btn primary" data-action="gem-upgrade" data-index="${index}" ${level>=PASSIVE_MAX_LEVEL?'disabled':''}>${level>=PASSIVE_MAX_LEVEL?`已满${PASSIVE_MAX_LEVEL}级`:'消耗1宝石升级'}</button>`;
    if(type==='equipment')actions=`<button class="btn secondary" data-action="move-hand" data-index="${index}">卸下到手牌</button><button class="btn danger" data-action="drop-build" data-type="equipment" data-index="${index}">公开丢弃</button>`;
    if(type==='hand')actions=`${[0,1,2].map(i=>`<button class="btn secondary" data-action="equip-hand" data-from="${index}" data-index="${i}">换到装备槽${i+1}</button>`).join('')}<button class="btn danger" data-action="drop-build" data-type="hand" data-index="${index}">公开丢弃</button>`;
    const status=type==='passive'?`Lv.${level} / ${PASSIVE_MAX_LEVEL}`:type==='active'?(m.activeCooldown?`CD ${m.activeCooldown}s · 无等级`:'READY · 无等级'):item.品质,location=type==='hand'?`手牌 · ${handRule}`:type==='equipment'?'身穿':type==='active'?'主动槽 · 1槽':'被动构筑';
    openWorldSheet(`构筑详情 · ${type.toUpperCase()}`,item.名称,`${worldItemCard(item,type==='hand'?'equipment':type)}<div class="interaction-facts"><span><b>${status}</b><small>当前状态</small></span><span><b>${type==='equipment'||type==='hand'?`卖价 ${item.卖价}`:'宝石 '+m.gems}</b><small>可用资源</small></span><span><b>${location}</b><small>所在位置</small></span></div><div class="world-sheet-actions">${actions}<button class="btn ghost" data-action="close-world-sheet">关闭</button></div>`,{type:'build',mode:'compact'});
  }
  function gemUpgrade(index){const e=state.match.passives[index];if(!e)return toast('被动实例已失效');normalizePassiveLevels();if(passiveLevel(e)>=PASSIVE_MAX_LEVEL)return toast(`该被动已满${PASSIVE_MAX_LEVEL}级`);if(state.match.gems<1)return toast('宝石不足');const before=passiveLevel(e);authority('GEM_UPGRADE',()=>state.match.passives[index]!==e?'被动实例已失效':passiveLevel(e)>=PASSIVE_MAX_LEVEL?`该被动已满${PASSIVE_MAX_LEVEL}级`:state.match.gems<1?'宝石不足':null,()=>{state.match.gems--;e.level=Math.min(PASSIVE_MAX_LEVEL,passiveLevel(e)+1);}).then(()=>{state.ui.gemUpgradeDismissedBalance=null;renderBuild();showGemUpgradeDock({force:true,source:'强化完成'});emitUIEvent(UI_EVENT_TYPES.SKILL_UPGRADE,{skillId:e.item.ID,fromLevel:before,toLevel:e.level,maxLevel:PASSIVE_MAX_LEVEL,costGem:1});uiSound('confirm');toast(`${e.item.名称} 升至Lv.${e.level}`,1500,'success');announce(`被动强化 · ${e.item.名称} Lv.${e.level}`);}).catch(error=>toast(error.message));}
  function moveHand(index){normalizeHand();const empty=state.match.hand.findIndex(x=>!x);if(empty<0)return toast('手牌已满；先处理手牌后再卸下');const item=state.match.equipment[index];if(!item)return;startChannel('卸下装备',.5,async()=>{state.match.hand[empty]=item;state.match.equipment[index]=null;normalizeHand();recalculateEquipmentStats({reason:'equipment-to-hand'});closeModal();closeWorldSheet();renderBuild();},['actualDamage','death']);}
