  function mapPoiInfo(kind,id=null){const chest=id&&state.chestWorld.instances.find(x=>x.instanceId===id),npc=id&&WORLD_MERCHANTS.find(x=>x.id===id),data=chest?[chest.kind==='airdrop'?'全局空投':'普通宝箱',`${chestDistanceMeters(chest).toFixed(1)}米 · ${chestRemaining(chest)}秒后失效`,`${chest.kind==='airdrop'?'3秒':'0.35秒'}引导；地图只能标记，不能隔空开启。`]:npc?[`${npc.name} · 已发现`,`${merchantDistance(npc).toFixed(1)}米 · 当前营业`,`靠近2.5米、保持直视并脱离玩家战斗${npc.kind==='taibai'?5:3}秒后可交互。`]:{boss:['核心首领 · 公共目标','万劫三庭 · 当前生命公开','进入可见、交战或公共关键阶段后可查看公开机制。'],loot:['遗宝堆','距离由实时世界坐标计算',`${isCoarseInput()?'靠近后点按交互键拾取；按住交互键打开附近列表。':'靠近后按E拾取；按住E打开附近列表。'}`]}[kind],box=$('#map-poi-detail');if(!data||!box)return;box.innerHTML=`<b>${data[0]}</b><small>${data[1]}</small><small>${data[2]}</small>${chest?`<button class="btn secondary" data-action="mark-chest" data-id="${chest.instanceId}">标记并返回战场</button>`:npc?`<button class="btn secondary" data-action="mark-merchant" data-id="${npc.id}">标记并返回战场</button>`:''}`;}
  function openHelp(){openModal('帮助 · D-02/D-08/R-03/R-04','操作与公平规则',`<div class="help-sections"><details open><summary>PC与手机操作</summary><p>PC：WASD移动，左键普攻，右键主动，E交互，M地图，按住TAB构筑，Space镜头回中，Esc菜单。手机：左摇杆移动；轻点主动智能施法，拖动精确瞄准；普攻按住连续攻击。</p></details><details><summary>三命与构筑</summary><p>每人三条命。前两次真死掉落全部手牌，第三次真死同时掉落手牌与身穿装备；复活后有3秒保护，任何进攻或交互输入会先解除保护。主动技能没有技能等级；被动才通过同名技能书或宝石升至最高5级。</p></details><details><summary>伤害与可读反馈</summary><p>命中先显示免疫、护盾吸收、实际扣血和控制结果，再更新生命条与伤害数字。未造成实际伤害的攻击不会伪报扣血；眩晕、击飞、沉默、定身和强制位移均显示独立状态与解除条件。</p></details><details><summary>迷雾与目标信息</summary><p>没有通用“最后已知位置”残影。范围技能盲放仍可命中隐身目标；显形不代表可以穿墙或穿烟锁定。灵魂飞行和观战不会得到私有背包或额外敌情。</p></details><details><summary>天劫与终局</summary><p>20:00前圈外每3秒独立判定雷击；20:00安全半径归零并进入灭世雷暴，20:01首跳，此后每秒命中且每5秒增加1%最大生命。</p></details><details><summary>交易与公开掉落</summary><p>商店不是安全区。玩家实际伤害会关闭交易；装备、技能书、Boss掉落和替换出的旧物立即公开，其他玩家可争夺。</p></details></div>`,{type:'help'});}
  function resultDetail(){const m=state.match,ledger=state.ui.modalContext?.ledger||calculateXiuwei(state.ui.modalContext?.rank||14,state.ui.modalContext?.aborted),cultivation=ledger.total;openModal('结算明细 · S-02/S-03','本局修为与最终构筑',`<div class="ledger"><span><b>活跃参与</b><strong>+${ledger.active}</strong></span><span><b>有效完赛</b><strong>+${ledger.completion}</strong></span><span><b>最终名次</b><strong>+${ledger.placement}</strong></span><span><b>玩家击败 × ${m.kills}</b><strong>+${ledger.kills}</strong></span><span><b>龙王末击</b><strong>+${ledger.dragon}</strong></span><span><b>核心Boss末击</b><strong>+${ledger.core}</strong></span><span class="total"><b>权威总计（上限200）</b><strong>+${cultivation}</strong></span></div><div class="build-inspector">${buildInspectorGroup('被动','passive',m.passives)}${buildInspectorGroup('装备','equipment',m.equipment)}${buildInspectorGroup('手牌','hand',m.hand)}${buildInspectorGroup('主动','active',[m.active])}</div><div class="modal-actions"><button class="btn secondary" data-action="close-modal">关闭明细</button></div>`,{type:'result-detail',ledger});}
  function openRecentDetail(index){const report=state.account.battleReports?.[index];if(!report)return toast('该战报尚未由服务器返回');const hero=state.maps.hero.get(report.heroId)||state.content.heroes[8],nodes=(report.storyNodes||[]).slice(0,8);openModal('最近对局 · V-01—V-15',`${report.settledAtLabel} · 第${report.placement}名`,`<section class="result-hero"><img src="${heroArt(hero,'avatar-512.png')}"><div><h3>${esc(hero.英雄)}</h3><p>${report.kills}击败 · 修为 +${report.xiuwei}</p></div><strong>#${report.placement}</strong></section><div class="battle-story">${nodes.length?nodes.map(n=>`<span><b>${esc(n.title)}</b><small>${esc(n.copy)}</small></span>`).join(''):'<div class="empty-state">本局无服务器关键事件节点</div>'}</div><div class="modal-actions"><button class="btn secondary" data-action="open-report" data-source="history">举报该局玩家</button><button class="btn ghost" data-action="close-modal">返回</button></div>`,{type:'recent',index,report});}
  function reportCandidates(){return (state.sim.actors||[]).filter(x=>x.hero).slice(0,29);}
  function openReport(source='result'){state.ui.reportCategory='';state.ui.reportTarget=null;const candidates=reportCandidates();openModal('举报 · X-01—X-11/S-08/S-14','选择本局玩家并举报',`<div class="notice">目标只能来自本局参与槽；成功后证据回放将延长保留。</div><div class="participant-picker">${candidates.length?candidates.map(x=>`<button data-action="select-report-target" data-id="${x.id}"><img src="${heroArt(x.hero,'avatar-512.png')}"><span><b>${esc(x.hero.英雄)}</b><small>参与槽 ${x.slot??x.id}</small></span></button>`).join(''):'<div class="empty-state">没有可举报的本局参与者</div>'}</div><div class="report-categories">${['作弊','重复预组队','冒犯昵称','利用漏洞','其他'].map(x=>`<button data-action="select-report-category" data-category="${x}">${x}</button>`).join('')}</div><label class="report-copy"><span>补充描述 <small id="report-count">0 / 500</small></span><textarea id="report-description" maxlength="500" placeholder="可选。请描述发生时间和行为，不要填写个人隐私。"></textarea></label><div class="modal-actions"><button class="btn danger" data-action="submit-report" disabled>提交举报</button><button class="btn ghost" data-action="close-modal">取消</button></div>`,{type:'report',source});}
  function selectReportTarget(id){state.ui.reportTarget=id;$$('.participant-picker button').forEach(x=>x.classList.toggle('active',x.dataset.id===id));const submit=$('[data-action="submit-report"]');if(submit)submit.disabled=!(state.ui.reportTarget&&state.ui.reportCategory);}
  function selectReportCategory(category){state.ui.reportCategory=category;$$('.report-categories button').forEach(x=>x.classList.toggle('active',x.textContent===category));const submit=$('[data-action="submit-report"]');if(submit)submit.disabled=!(state.ui.reportTarget&&state.ui.reportCategory);}
  function submitReport(){const description=$('#report-description')?.value||'';authority('SUBMIT_REPORT',()=>!state.ui.reportTarget?'请选择本局玩家':!state.ui.reportCategory?'请选择举报分类':description.length>500?'描述不能超过500字':null,()=>({reportId:`RP-${Date.now().toString(36).toUpperCase()}`,target:state.ui.reportTarget})).then(result=>openModal('举报已提交 · X-03/X-08','感谢你的反馈',`<div class="success-state"><i>✓</i><h3>举报编号 ${result.reportId}</h3><p>证据回放保留期已延长。</p></div><div class="modal-actions"><button class="btn primary" data-action="close-modal">完成</button></div>`,{type:'report-success'})).catch(e=>toast(e.message));}
  function updateLikePicker(){const list=state.ui.likeSelection||[],atLimit=list.length>=3,count=$('#like-count'),submit=$('[data-action="submit-likes"]');$$('.like-picker .like-avatar').forEach(node=>{const selected=list.includes(node.dataset.id);node.classList.toggle('active',selected);node.classList.toggle('limit-muted',atLimit&&!selected);node.setAttribute('aria-pressed',String(selected));node.setAttribute('aria-disabled',String(atLimit&&!selected));});if(count)count.textContent=`已选 ${list.length}/3`;if(submit){submit.disabled=!list.length;submit.textContent=list.length?`点赞 ${list.length} 人`:'请选择头像';}}
  function startLikeCountdown(deadline){if(state.ui.likeTimer)clearTracked(state.ui.likeTimer);const update=()=>{if(state.ui.modalContext?.type!=='likes'){if(state.ui.likeTimer)clearTracked(state.ui.likeTimer);state.ui.likeTimer=null;return;}const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000)),node=$('#like-deadline');if(node)node.textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(!remaining){$$('.like-picker button,[data-action="submit-likes"]').forEach(x=>x.disabled=true);if(node)node.textContent='已结束';if(state.ui.likeTimer)clearTracked(state.ui.likeTimer);state.ui.likeTimer=null;}};update();state.ui.likeTimer=trackTimer(setInterval(update,1000));}
  function openLikes(){const candidates=reportCandidates(),deadline=Date.now()+300000;state.ui.likeSelection=[];openModal('赛后点赞','选头像即可点赞',`<section class="like-summary"><span><b>最多 3 人</b><small>不可点赞自己 · 提交后不可撤回 · 无玩法奖励</small></span><strong id="like-count">已选 0/3</strong><time id="like-deadline">05:00</time></section><div class="participant-picker like-picker" role="group" aria-label="选择本局点赞玩家">${candidates.map(x=>`<button class="like-avatar" data-action="toggle-like" data-id="${x.id}" aria-pressed="false" aria-label="点赞 ${esc(x.hero.英雄)}" title="${esc(x.hero.英雄)}"><span><img src="${heroArt(x.hero,'avatar-512.png')}" alt="${esc(x.hero.英雄)}头像"><i>✓</i></span></button>`).join('')}</div><div class="modal-actions like-actions"><button class="btn ghost" data-action="close-modal">跳过</button><button class="btn primary" data-action="submit-likes" disabled>请选择头像</button></div>`,{type:'likes',deadline});startLikeCountdown(deadline);}
  function toggleLike(id){const list=state.ui.likeSelection||[],at=list.indexOf(id);if(at>=0)list.splice(at,1);else if(list.length<3)list.push(id);else return tactileFeedback('blocked');tactileFeedback('tap');updateLikePicker();}
  function submitLikes(){if(Date.now()>state.ui.modalContext.deadline)return toast('点赞窗口已结束');const targets=[...(state.ui.likeSelection||[])];if(!targets.length)return;authority('SUBMIT_LIKES',null,()=>targets).then(()=>{if(state.ui.likeTimer){clearTracked(state.ui.likeTimer);state.ui.likeTimer=null;}openModal('赛后点赞 · COMMITTED','点赞已提交',`<div class="success-state"><i>赞</i><h3>已为${targets.length}名玩家点赞</h3><p>每个目标本局仅一次，提交后不可撤回。</p></div><div class="modal-actions"><button class="btn primary" data-action="close-modal">完成</button></div>`,{type:'likes-success'});});}
  function openBattleMenu(){openModal('对局菜单','对局菜单',`<div class="choice-grid battle-menu-grid"><button class="choice-card primary-return" data-action="close-modal"><b>继续战斗</b><small>立即返回战场</small></button><button class="choice-card" data-action="battle-settings"><b>对局设置</b><small>画质、音频、无障碍、输入</small></button><button class="choice-card" data-action="help"><b>帮助</b><small>操作与玩法说明</small></button><button class="choice-card danger-choice" data-action="request-leave-match"><b>退出本局</b><small>主动退出将按失败结算</small></button></div>`,{type:'menu'});}
  function requestLeaveMatch(){openModal('主动退出','确认退出本局？',`<div class="leave-match-warning"><strong>败</strong><div><h3>本局将立即按失败结算</h3><p>当前名次、构筑与局内金币不会带回大厅；确认后无法撤销。</p></div></div><div class="modal-actions"><button class="btn ghost" data-action="close-modal">继续战斗</button><button class="btn danger" data-action="confirm-leave-match">确认退出并记为失败</button></div>`,{type:'leave-confirm'});}
  function confirmLeaveMatch(){if(!state.match)return navigateRoot('lobby');state.match.alive=false;state.match.seatValid=false;state.match.status='FORFEIT_LOSS';emitUIEvent(UI_EVENT_TYPES.STATUS,{status:'FORFEIT_LOSS',result:'LOSS'});localStorage.setItem('sanming-completed-matches',String(Number(localStorage.getItem('sanming-completed-matches')||0)+1));stopBattleClock();stopLiveSimulation();closeModal(false);renderLobby();navigateRoot('lobby');toast('已退出本局 · 本局计为失败',2800,'danger');tactileFeedback('danger');}

  function renderGrowth(){if(state.ui.growthTab==='cultivation')renderCultivation();else renderCodex();$$('[data-meta-tab]').forEach(b=>b.classList.toggle('active',b.dataset.metaTab===state.ui.growthTab));}
  function xiuweiTrack(){const rows=[];for(let i=0;i<50;i++){const read=suffix=>sourceRule(47,`xiuwei.track[${i}].${suffix}`,'');const level=Number(read('level'))||i+1,realm=read('realm_zh')||realmForLevel(level),required=Number(read('required_from_previous'))||XIUWEI_FALLBACK[i]?.[2]||0,cumulative=Number(read('cumulative'))||XIUWEI_FALLBACK[i]?.[3]||0,reward=read('reward_zh')||XIUWEI_FALLBACK[i]?.[4]||'纯外观奖励';rows.push({level,realm,required,cumulative,reward});}return rows;}
  function growthRewardVisual(reward=''){if(/头像框|边框/.test(reward))return['框','frame'];if(/称号|名号/.test(reward))return['名','title'];if(/头像/.test(reward))return['像','avatar'];if(/铭牌|名片/.test(reward))return['牌','plate'];if(/特效|光效|尾迹/.test(reward))return['辉','effect'];return['饰','cosmetic'];}
  function renderCultivation(){const track=xiuweiTrack(),current=[...track].reverse().find(x=>state.account.cultivation>=x.cumulative)||track[0],next=track[current.level]||current;state.account.level=current.level;state.account.realm=current.realm;state.account.next=next.cumulative;$('#growth-content').innerHTML=`<div class="cultivation-layout"><article class="realm-summary"><p class="eyebrow">当前修为 · Lv.${current.level}</p><h3>${current.realm}</h3><b>${state.account.cultivation.toLocaleString()} / ${next.cumulative.toLocaleString()}</b><div class="big-progress" aria-label="本级修为进度"><i style="width:${next.cumulative===current.cumulative?100:100*(state.account.cultivation-current.cumulative)/(next.cumulative-current.cumulative)}%"></i></div><p>修为只增不减，单局最多200。挂机/BOT托管时段不获得活跃修为；全部奖励仅改变外观与身份表达。</p><div class="realm-chips">${realms.map(r=>`<span class="${current.realm.startsWith(r)?'active':''}">${r}</span>`).join('')}</div><div class="growth-legend"><span class="done">✓ 已解锁</span><span class="now">◆ 当前</span><span class="locked">◇ 未解锁</span></div></article><section class="realm-track-shell"><header><span><b>50级外观轨道</b><small>默认定位当前等级，可左右浏览全部奖励</small></span><strong>Lv.${current.level} / 50</strong></header><div class="realm-track level-track">${track.map(x=>{const stateName=x.level<current.level?'unlocked':x.level===current.level?'current':'future',stateCopy=stateName==='future'?`还需${Math.max(0,x.cumulative-state.account.cultivation)}修为`:stateName==='current'?'当前等级':'已解锁',[glyph,rewardType]=growthRewardVisual(x.reward);return `<button class="realm-node ${stateName} reward-${rewardType}" data-action="growth-reward" data-level="${x.level}" aria-label="${stateCopy}，Lv.${x.level} ${x.realm}，${esc(x.reward)}"><em class="realm-node-state">${stateName==='unlocked'?'✓':stateName==='current'?'◆':'◇'}</em><i data-reward-glyph="${glyph}">${x.level}</i><b>Lv.${x.level} · ${x.realm}</b><small>${esc(x.reward)}</small><span>${stateCopy}</span></button>`;}).join('')}</div><div class="track-scroll-hint" aria-hidden="true"><i></i><span>拖动 / 滚轮继续查看</span></div></section></div>`;requestAnimationFrame(()=>$('#growth-content .realm-node.current')?.scrollIntoView({behavior:'instant',block:'nearest',inline:'center'}));}
  function growthReward(level){const item=xiuweiTrack().find(x=>x.level===level),unlocked=state.account.cultivation>=item.cumulative;openModal('修为奖励 · T-01—T-10',`Lv.${level} · ${item.reward}`,`<div class="reward-preview"><i>${level}</i><div><h3>${unlocked?'已由服务端确认解锁':'尚未解锁'}</h3><p>${esc(item.reward)}；累计门槛 ${item.cumulative.toLocaleString()}。该奖励只改变外观表达，不增加攻击、生命、移速、掉率、折扣或复活。</p></div></div>`,{type:'growth-reward'});}
  function collectionFor(category){if(category==='heroes')return state.content.heroes.map(x=>({...x,_type:'hero'}));if(category==='exclusive')return state.content.actives.filter(x=>x.类型==='专属').map(x=>({...x,_type:'active'}));if(category==='generic')return state.content.actives.filter(x=>x.类型!=='专属').map(x=>({...x,_type:'active'}));if(category==='passives')return state.content.passives.map(x=>({...x,_type:'passive'}));return state.content.equipment.map(x=>({...x,_type:'equipment'}));}
  function collectionStage(item){return state.account.collectionStates[item.ID]||'未发现';}
  function renderCodex(){const tabs=[['heroes','英雄 · 38'],['exclusive','专属主动 · 38'],['generic','通用主动 · 19'],['passives','被动 · 44'],['equipment','装备 · 48']],list=collectionFor(state.ui.codexCategory),used=list.filter(item=>['用过','精通'].includes(collectionStage(item))).length,pct=list.length?Math.floor(used/list.length*100):0,threshold=[25,50,75,100].find(x=>x>pct)||100;$('#growth-content').innerHTML=`<section class="codex-shell"><nav class="codex-sidebar">${tabs.map(x=>`<button class="${state.ui.codexCategory===x[0]?'active':''}" data-action="codex-category" data-category="${x[0]}">${x[1]}</button>`).join('')}</nav><div class="codex-main"><header class="codex-summary"><div class="codex-progress-copy"><b>收集历程</b><span>未发现 → 见过 → 用过 → 精通</span></div><div class="codex-progress-value"><strong>${used}/${list.length}</strong><span>已用过 · ${pct}%</span></div><div class="codex-progress-meter" role="progressbar" aria-label="本分类图鉴进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><div class="codex-thresholds" aria-label="图鉴里程碑奖励">${[25,50,75,100].map(x=>{const claimed=state.account.collectionRewardClaims.includes(x),eligible=pct>=x;return `<button data-action="codex-reward" data-threshold="${x}" ${!eligible||claimed?'disabled':''} aria-label="${x}%里程碑，${claimed?'已领取':eligible?'可领取':`还差${x-pct}%`}"><b>${x}%</b><small>${claimed?'已领取':eligible?'可领取':`还差${x-pct}%`}</small></button>`;}).join('')}</div><em>${pct<100?`下一奖励 ${threshold}%`:'分类已完成'} · 奖励仅限外观</em><small>全部进度与领取状态必须由账号服务返回；当前未连接时保持真实的0进度，不伪造已解锁项。</small></header><div class="codex-grid">${list.map(item=>codexCard(item)).join('')}</div></div></section>`;}
  function codexCard(item){const stage=collectionStage(item),locked=stage==='未发现',kind=item._type==='hero'?'hero':item._type,isHero=item._type==='hero',src=isHero?heroArt(item,'foreground-v2.png'):itemIcon(kind,item.ID),name=item.英雄||item.名称;return `<button class="codex-card ${locked?'locked':''} ${isHero?'hero-portrait':''}" data-action="codex-detail" data-type="${item._type}" data-id="${item.ID}" ${isHero?`data-hero-focus="${item.ID}" style="${heroPortraitStyle(item)}"`:''} ${locked?'disabled':''}><i class="codex-state">${stage}</i><img src="${src}" alt=""><span><b>${locked?'未发现':esc(name)}</b><small>${locked?'在对局中直接见到后解锁':esc(item.五行||item.类别||item.品质||item.类型)}</small></span></button>`;}
  function activeShape(item){const geometry=String(item?.瞄准与几何||''),mechanism=String(item?.完整机制||'');return mechanism.includes('SPAWN')?'summon':geometry.includes('LINE_WALL')?'wall':geometry.includes('SELF')?'self':geometry.includes('CIRCLE')?'circle':geometry.includes('CONE')?'cone':geometry.includes('POINT')?'point':'line';}
  function activePreviewHTML(item){if(!item)return '';const shape=activeShape(item),geometry=String(item.瞄准与几何||'');return `<section class="skill-preview-shell"><header><div><b>交互动画与引擎时序</b><small>${esc(item.ID)} · ${esc(geometry)}</small></div><button class="btn secondary" data-action="preview-active" data-id="${item.ID}">重新预演</button></header><div class="skill-preview ${shape}" data-active-preview="${item.ID}"><i></i><span></span><b>${esc(item.名称)}</b></div><ol class="effect-timeline"><li><b>瞄准</b><small>合法目标/方向/落点与取消</small></li><li><b>前摇</b><small>本地预演，不先判成功</small></li><li><b>权威提交</b><small>锁定effect_id与服务端tick</small></li><li><b>弹道/区域/命中</b><small>按真源几何和碰撞重建</small></li><li><b>残留/结束</b><small>真死、失效、重连均清理</small></li></ol><div class="notice">HTML定义交互、状态和时序；Unity/游戏引擎按同一 effect_id、几何、tick锚点、音频与低闪替代重建最终粒子效果。</div></section>`;}
  function replayActivePreview(id){const item=state.maps.active.get(id),node=$(`[data-active-preview="${id}"]`);if(!item||!node)return;const shape=activeShape(item);node.className='skill-preview';void node.offsetWidth;node.className=`skill-preview ${shape}`;}
  function codexDetail(type,id){let item=type==='hero'?state.maps.hero.get(id):type==='active'?state.maps.active.get(id):type==='passive'?state.maps.passive.get(id):state.maps.equipment.get(id);const name=item.英雄||item.名称,src=type==='hero'?heroArt(item):itemIcon(type,item.ID),active=type==='hero'?heroActive(item):type==='active'?item:null,rarity=rarityClass(item,type);let copy=type==='hero'?`L1 ${item['L1攻/血/速']}；L15 ${item['L15攻/血/速']}；射程/攻速 ${item['射程/攻速']}；专属主动 ${active.名称}。`:playerText(item,type);openModal('强类型图鉴详情 · U-08',name,`<div class="service-hero ${rarity}"><span class="item-art ${rarity}"><img src="${src}"></span><div><h3>${esc(name)}</h3><p>${esc(copy)}</p><p>精通条件：${type==='hero'?'正式出生并有效输入，或使用该英雄进入前3。':type==='passive'?'学到1级并升到5级。':type==='equipment'?'成功穿戴，且前3时穿戴120秒或完成触发。':'成功施放，并使用该主动进入前3。'}</p></div>${type==='equipment'?qualityBadge(item):''}</div>${activePreviewHTML(active)}`,{type:'codex'});}
