  function openExportTask(){const job=state.exportJob;if(!job)return openModal('数据导出 · Y-12/Y-20','导出账号数据','<div class="notice">导出包含账号资料、设置、最近对局和图鉴状态；不包含隐藏MMR、反作弊信号或其他玩家私有数据。</div><div class="modal-actions"><button class="btn primary" data-action="start-export">创建导出任务</button><button class="btn ghost" data-action="close-modal">取消</button></div>',{type:'export'});openModal('数据导出 · Y-20',`任务 ${job.id}`,`<div class="export-progress"><i style="width:${job.progress}%"></i></div><div class="notice">状态：${job.status} · ${job.progress}%${job.status==='就绪'?' · 下载链接24小时后过期':''}</div><div class="modal-actions">${job.status==='就绪'?'<button class="btn primary" data-action="download-export">下载导出包</button>':'<button class="btn secondary" data-action="refresh-export">刷新状态</button>'}<button class="btn ghost" data-action="close-modal">稍后查看</button></div>`,{type:'export-job'});}
  function startExport(){authority('CREATE_EXPORT',null,()=>state.exportJob={id:`EX-${Date.now().toString(36).toUpperCase()}`,status:'处理中',progress:18}).then(()=>{openExportTask();toast('导出任务已创建');});}
  function refreshExport(){state.exportJob.progress=Math.min(100,state.exportJob.progress+41);if(state.exportJob.progress===100)state.exportJob.status='就绪';openExportTask();}
  function openDeleteAccount(){if(state.deleteCooling)return openModal('账号删除 · Y-13/Y-21','删除冷静期进行中',`<div class="notice danger">剩余 ${state.deleteCooling} 天。冷静期内账号仍可正常使用；取消后不会删除数据。</div><div class="modal-actions"><button class="btn danger" data-action="cancel-delete">取消删除申请</button><button class="btn ghost" data-action="close-modal">返回</button></div>`,{type:'delete-cooling'});openModal('危险操作 · Y-13/Y-21','申请删除账号',`<div class="notice danger">提交后进入7天冷静期；到期由服务端执行匿名化。请输入“删除我的账号”确认。</div><label class="report-copy"><span>确认短语</span><input id="delete-phrase" autocomplete="off" placeholder="删除我的账号"></label><div class="modal-actions"><button class="btn danger" data-action="confirm-delete" disabled>进入7天冷静期</button><button class="btn ghost" data-action="close-modal">取消</button></div>`,{type:'delete-confirm'});}
  function confirmDelete(){authority('REQUEST_DELETE',()=>$('#delete-phrase')?.value!=='删除我的账号'?'确认短语不匹配':null,()=>state.deleteCooling=7).then(()=>{openDeleteAccount();toast('删除申请已提交');}).catch(e=>toast(e.message));}
  function cancelDelete(){authority('CANCEL_DELETE',null,()=>state.deleteCooling=0).then(()=>{closeModal();toast('删除申请已取消');});}
  function renderAccount(){const unbound=['邮箱','手机号','海外平台'].filter(x=>!state.account.bound.includes(x)),secure=unbound.length===0;$('#account-content').innerHTML=`<article class="account-card identity-card"><div class="account-card-head"><span><p class="eyebrow">当前身份</p><h3>账号已自动建立</h3></span><i class="security-badge ${secure?'complete':'attention'}">${secure?'✓ 已保护':'! 待保护'}</i></div><p>当前安装凭据有效。未绑定时不能承诺跨设备找回；不存在“游客/正式”二选一。</p><div class="account-actions">${unbound.map(x=>`<button class="btn secondary identity-option" data-action="bind-identity" data-kind="${x}"><i>${x==='邮箱'?'邮':x==='手机号'?'号':'海'}</i><span><b>绑定${x}</b><small>${x==='邮箱'?'用于找回与跨设备':x==='手机号'?'支持国际区号':'Apple / Google / Steam'}</small></span><em>›</em></button>`).join('')||'<div class="notice success">✓ 已绑定所有可用身份。</div>'}<button class="btn ghost merge-option" data-action="merge-preview">账号合并预览 <small>仅在身份已被其他账号占用时使用</small></button></div></article><article class="account-card device-card"><div class="account-card-head"><span><p class="eyebrow">设备会话</p><h3>${state.account.sessions.length} / 3 台设备</h3></span><i class="device-capacity ${state.account.sessions.length>=3?'full':''}">${3-state.account.sessions.length} 空位</i></div><div class="device-list">${state.account.sessions.map((x,i)=>`<div class="device-row ${x.current?'current':'remote'}"><i class="device-icon">${x.current?'本':'远'}</i><span><b>${x.name}</b><small>${x.region} · ${x.active}</small></span>${x.current?'<em>当前设备</em>':`<button class="btn danger subtle" data-action="revoke-session" data-index="${i}">撤销</button>`}</div>`).join('')}</div><button class="btn secondary fourth-device" data-action="fourth-device">预演第四台设备登录</button></article>`;}
  function bindIdentity(kind){state.pendingBinding={kind,step:'IDENTITY'};openModal('账号绑定 · BIND',`绑定${kind}`,`<div class="notice">绑定请求使用POST /v2/account/bind；如凭证已占用，必须先进入账号合并预览。</div><label class="setting-row"><span><b>${kind==='邮箱'?'邮箱地址':kind==='手机号'?'国际手机号':'海外平台账号'}</b><small>${kind==='邮箱'?'例如 name@example.com':kind==='手机号'?'包含国际区号，例如 +86':'选择平台并完成授权'}</small></span>${kind==='海外平台'?'<select id="bind-value"><option>Apple</option><option>Google</option><option>Steam</option></select>':`<input id="bind-value" type="${kind==='邮箱'?'email':'tel'}" autocomplete="off" placeholder="请输入${kind}">`}</label><div class="modal-actions"><button class="btn primary" data-action="submit-binding" data-kind="${kind}">继续验证</button><button class="btn ghost" data-action="close-modal">取消</button></div>`,{type:'binding',kind});}
  function submitBinding(kind){const value=$('#bind-value')?.value?.trim();if(!value)return toast(`请输入${kind}`);openModal('账号绑定 · VERIFY',`验证${kind}`,`<div class="success-state"><i>码</i><h3>验证请求已发送</h3><p>输入6位验证码；海外平台由授权回调生成provider_token。</p></div><label class="report-copy"><span>验证码</span><input id="bind-code" inputmode="numeric" maxlength="6" placeholder="000000"></label><div class="modal-actions"><button class="btn primary" data-action="commit-binding" data-kind="${kind}">提交绑定</button><button class="btn ghost" data-action="bind-identity" data-kind="${kind}">返回修改</button></div>`,{type:'binding-verify',kind,value});}
  function commitBinding(kind){const code=$('#bind-code')?.value?.trim();if(!/^\d{6}$/.test(code||''))return toast('请输入6位验证码');authority('ACCOUNT_BIND',null,()=>({account_id:state.account.id,bind_state:'BOUND'})).then(()=>{if(!state.account.bound.includes(kind))state.account.bound.push(kind);openModal('账号绑定 · COMMITTED',`${kind}绑定成功`,`<div class="success-state"><i>✓</i><h3>跨设备找回已启用</h3><p>绑定结果已写入当前账号，不创建第二个游戏身份。</p></div><div class="modal-actions"><button class="btn primary" data-action="binding-finish">完成</button></div>`,{type:'binding-success'});});}
  function fourthDevice(){if(state.account.sessions.length<3)state.account.sessions.push({name:'旧设备 · Android',region:'CN',active:'5天前',current:false});openModal('设备上限 · B-08/B-14/B-15','选择一台旧设备撤销',`<div class="notice danger">第4台设备不会自动挤掉任意会话。必须明确选择一台旧设备；撤销完成且快照就绪后，新设备才能进入。</div><div class="device-choice">${state.account.sessions.map((x,i)=>x.current?'':`<button data-action="confirm-fourth-device" data-index="${i}"><b>${x.name}</b><small>${x.region} · ${x.active}</small></button>`).join('')}</div><div class="modal-actions"><button class="btn ghost" data-action="close-modal">取消登录</button></div>`,{type:'fourth-device'});}
  function confirmFourthDevice(index){authority('REVOKE_FOR_FOURTH_DEVICE',()=>state.account.sessions[index]?.current?'不能撤销当前设备':null,()=>{state.account.sessions.splice(index,1);state.account.sessions.push({name:'新设备 · iPhone 17 Pro',region:'CN',active:'刚刚授权',current:false});}).then(()=>{closeModal();renderAccount();toast('旧会话已撤销 · 新设备快照已就绪');});}
  function revokeSession(index){const session=state.account.sessions[index];openModal('会话撤销 · B-09',`撤销「${session.name}」？`,`<div class="notice danger">被撤设备将立即断线；当前设备不会退出。</div><div class="modal-actions"><button class="btn danger" data-action="confirm-revoke" data-index="${index}">确认撤销</button><button class="btn ghost" data-action="close-modal">取消</button></div>`,{type:'account'});}
  const STORE_STATE_DATASET=Object.freeze({ready:'目录就绪',loading:'加载中',empty:'当前分类暂无商品',partial:'部分卡片加载失败',soldout:'售罄/下架',region:'当前地区不可用',owned:'已拥有',limit:'数量上限',insufficient:'余额不足',priceChanged:'价格版本变化',duplicate:'重复请求',lateReceipt:'迟到回执',ageRestricted:'地区/年龄限制',paymentCancelled:'支付取消',paymentFailed:'支付失败',reconnect:'重连恢复'});
  const STORE_CATALOG=Object.freeze({
    skin:[{id:'SKIN_H009_A',name:'齐天战甲',type:'英雄皮肤',copy:'纯外观；不得改变碰撞、攻击帧、射程、技能预警、声音辨识或可见性。',hero:'H009',price:'¥30.00',owned:false},{id:'SKIN_H001_A',name:'云海仙衣',type:'英雄皮肤',copy:'适用铁扇公主；不改变五行、伤害或视野。',hero:'H001',price:'¥30.00',owned:true},{id:'SKIN_H014_A',name:'玄金战袍',type:'英雄皮肤',copy:'适用二郎神；公平表现与默认外观等价。',hero:'H014',price:'¥30.00',owned:false}],
    mount:[{id:'MOUNT_CLOUD',name:'流云飞骑',type:'飞行坐骑',copy:'外观预览；不得绕过天生飞行、G4、地形、交互距离与战斗公平。',hero:'H009',price:'¥68.00',owned:false},{id:'MOUNT_CRANE',name:'丹羽仙鹤',type:'飞行坐骑',copy:'只做隔离预览；正式权威移动合同未闭合。',hero:'H026',price:'¥68.00',owned:false}],
    revive:[{id:'REVIVE_COIN',name:'复活币',type:'可堆叠消耗品',copy:'不得接入正式对局；三命、名次、MMR、结算、消耗时点及地区商业规则未写入真源。',hero:'H009',price:'¥6.00',owned:false,count:0,limit:9}]
  });
  function renderStore(){const tab=state.ui.storeTab||'skin',status=state.ui.storeState||'ready',items=STORE_CATALOG[tab]||[];$$('[data-store-tab]').forEach(button=>button.classList.toggle('active',button.dataset.storeTab===tab));const statusBar=state.ui.qaEnabled?`<div class="prototype-state-strip store-prototype-states" data-layer="PROTOTYPE_ONLY"><b>隔离状态：</b>${Object.entries(STORE_STATE_DATASET).map(([id,label])=>`<button data-action="store-prototype-state" data-state="${id}" class="${status===id?'active':''}">${label}</button>`).join('')}</div>`:'';
    if(status==='loading')return $('#store-content').innerHTML=`${statusBar}<section class="unavailable-state"><i>商</i><h3>正在加载隔离目录</h3><p>不预扣款、不本地发货。</p></section>`;
    if(['empty','region'].includes(status))return $('#store-content').innerHTML=`${statusBar}<section class="unavailable-state"><i>商</i><h3>${STORE_STATE_DATASET[status]}</h3><p>${status==='region'?'地区结果由服务端决定，切换语言不能绕过。':'返回其他分类继续预览。'}</p></section>`;
    const cards=items.map((item,index)=>{const forcedSold=status==='soldout'&&index===0,partial=status==='partial'&&index===1,limited=item.count>=item.limit||status==='limit';return `<article class="store-card ${forcedSold?'sold':''} ${partial?'failed':''}" data-store-item="${item.id}">${partial?'<div class="store-card-failure"><b>缩略图加载失败</b><small>其他商品仍可查看</small></div>':`<img src="${heroArt(state.maps.hero.get(item.hero)||state.content.heroes[0],'foreground-v2.png')}" alt="${esc(item.name)}">`}<span class="store-type">${item.type}</span><h3>${item.name}</h3><p>${item.copy}</p><div class="store-card-meta"><span>${item.type==='可堆叠消耗品'?`持有 ${item.count}/${item.limit}`:item.owned||status==='owned'?'已拥有':'未拥有'}</span><strong>${item.price}</strong></div><button class="btn secondary" data-action="store-detail" data-id="${item.id}" data-tab="${tab}" ${forcedSold||partial?'disabled':''}>${forcedSold?'已下架':partial?'不可用':'查看详情'}</button>${limited?'<small class="store-limit-copy">已达数量上限</small>':''}</article>`;}).join('');
    $('#store-content').innerHTML=`${statusBar}<div class="store-hold-notice"><b>S-HOLD-05 · PROTOTYPE_ONLY · STORE_DISABLED</b><span>完整布局仅供开发；首发生产入口隐藏、无SKU、无真实价格、无充值、无支付、无权益发货。</span></div>${cards}`;
  }
  function storeItemById(id){return Object.values(STORE_CATALOG).flat().find(item=>item.id===id);}
  function openStoreDetail(id,tab){const item=storeItemById(id);if(!item)return;const status=state.ui.storeState||'ready',disabled=item.owned||status==='owned'||status==='soldout'||status==='region'||(item.count??0)>=(item.limit??Infinity);openModal('S-HOLD-05 · PROTOTYPE_ONLY',item.name,`<section class="store-detail-layout"><div class="store-preview-stage"><img src="${heroArt(state.maps.hero.get(item.hero)||state.content.heroes[0],'foreground-v2.png')}" alt=""><span>组合预览 · 不进入生产所有权</span></div><article><p class="eyebrow">${item.type}</p><h3>${item.name}</h3><p>${item.copy}</p><div class="interaction-facts"><span><b>${item.price}</b><small>模拟价格</small></span><span><b>${item.type==='可堆叠消耗品'?`持有 ${item.count}/${item.limit}`:item.owned?'已拥有':'未拥有'}</b><small>模拟所有权</small></span><span><b>平台支付占位</b><small>未接真实支付</small></span></div><div class="interaction-warning danger">${item.type==='可堆叠消耗品'?'复活币不得接入正式对局，不能改变三命、名次、MMR或结算。':'不得改变碰撞、帧、射程、预警、声音、可见性、飞行资格、地形或交互距离。'}</div><div class="modal-actions"><button class="btn primary" data-action="store-purchase-confirm" data-id="${item.id}" data-tab="${tab}" ${disabled?'disabled':''}>${item.owned||status==='owned'?'已拥有':(item.count??0)>=(item.limit??Infinity)?'数量上限':'直接购买'}</button><button class="btn ghost" data-action="close-modal">返回商品列表</button></div></article></section>`,{type:'store',id:item.id,tab});}
  function storePurchaseConfirm(id,tab){const item=storeItemById(id);if(!item)return;openModal('S-HOLD-05 · 购买确认',`确认购买「${item.name}」？`,`<div class="purchase-receipt"><span><b>商品</b><strong>${item.name}</strong></span><span><b>数量</b><strong>1</strong></span><span><b>价格</b><strong>${item.price}</strong></span><span><b>支付来源</b><strong>平台支付占位</strong></span></div><div class="interaction-warning danger">这是隔离状态演示。确认后只预演权威结果，不扣款、不发货、不可进入正式对局。</div><div class="modal-actions"><button class="btn primary" data-action="store-purchase-submit" data-id="${item.id}" data-tab="${tab}">确认购买</button><button class="btn ghost" data-action="store-detail" data-id="${item.id}" data-tab="${tab}">返回详情</button></div>`,{type:'store-confirm',id:item.id,tab});}
  function storePurchaseSubmit(id,tab){const item=storeItemById(id),status=state.ui.storeState||'ready',copy={insufficient:'余额不足，未扣款。',priceChanged:'价格版本变化，请返回详情确认新价格。',duplicate:'重复请求已由幂等键拒绝。',lateReceipt:'迟到回执已核对订单状态，不重复发货。',ageRestricted:'地区/年龄限制，当前不可购买。',paymentCancelled:'支付已取消。',paymentFailed:'支付失败，未发货。',reconnect:'重连后恢复订单查询，未发现可交付权益。'}[status];if(copy)return openModal('S-HOLD-05 · 购买结果',STORE_STATE_DATASET[status],`<div class="interaction-warning danger">${copy}</div><div class="modal-actions"><button class="btn secondary" data-action="store-detail" data-id="${item.id}" data-tab="${tab}">返回商品详情</button><button class="btn ghost" data-action="close-modal">关闭</button></div>`,{type:'store-result'});openModal('S-HOLD-05 · 演示完成','未执行真实购买','<div class="success-state"><i>✓</i><h3>交互路径验证通过</h3><p>未扣款、未发货、未改变所有权；正式接入必须等待SKU、税费、地区、平台支付和权益合同闭合。</p></div><div class="modal-actions"><button class="btn primary" data-action="close-modal">完成</button></div>',{type:'store-result'});}

  function genericStateModal(item){state.ui.prototypeState=item.id;openModal(`${item.ids} · STATE_DATASET`,item.title,`<section class="state-machine-card"><header><span class="state-pulse"></span><div><p class="eyebrow">${item.group}</p><h3>${item.title}</h3></div><b>${item.terminal?'不可重试':'可恢复'}</b></header><p>${item.copy}</p><ol><li class="done">事件已识别</li><li class="active">等待权威状态</li><li>执行玩家动作</li><li>恢复唯一去向</li></ol></section><div class="modal-actions"><button class="btn ${item.terminal?'secondary':'primary'}" data-action="prototype-state-primary" data-state="${item.id}">${item.primary}</button><button class="btn ghost" data-action="close-modal">返回验收集</button></div>`,{type:'prototype-state',stateId:item.id});}
  function openPrototypeState(id){const item=prototypeStates.find(x=>x.id===id);if(!item)return;state.ui.qaOpen=false;$('#qa-panel').hidden=true;
    if(id==='merge')return openMergePreview();if(id==='aim'||id==='dual-target'||id==='trap')return openAimDataset(id);if(id==='loot-heap')return openLootHeap();if(id==='alchemy')return openAlchemy();if(id==='spectate')return openSpectateDataset();if(id==='monster')return openMonsterDataset();if(id==='airdrop-warning'){ensureBattle();showWarning('空投即将抵达','15秒后生成公开落点 · 低闪模式使用边框脉冲',4200);playVfx('circle','AIRDROP_WARNING');return toast('空投预警已在战斗HUD预演');}if(id==='weak-network'){ensureBattle();return showSystem('网络质量下降','移动预测仅限本地；交易、命中与奖励等待服务器。连接中断后进入3秒宽限。','<button class="btn primary" data-action="qa-disconnect">模拟断线</button><button class="btn ghost" data-action="recover-control">保持当前连接</button>');}if(id==='graphics-recovery')return showSystem('画面正在恢复','已冻结渲染输入；席位和网络连接仍保持。正在重建GPU资源并同步权威快照。','<button class="btn primary" data-action="prototype-state-primary" data-state="graphics-recovery">重试画面恢复</button>');genericStateModal(item);
  }
  function prototypeStatePrimary(id){const item=prototypeStates.find(x=>x.id===id);if(!item)return;if(id==='protocol'){closeModal();return toast('协议版本已确认，继续原启动步骤');}if(item.terminal){return openModal(`${item.ids} · TERMINAL`,item.title,`<div class="notice danger">该状态不能通过重试或切换语言绕过。玩家可查看支持说明并安全结束应用。</div><div class="modal-actions"><button class="btn secondary" data-action="close-modal">返回</button></div>`,{type:'terminal'});}const button=$(`[data-action="prototype-state-primary"][data-state="${id}"]`);if(button){button.disabled=true;button.textContent='正在确认…';}authority(`STATE_${id.toUpperCase()}`,null,()=>true).then(()=>{if($('#system-overlay')&&!$('#system-overlay').hidden){$('#system-overlay').hidden=true;toast('画面资源已重建 · 权威快照一致');return;}openModal(`${item.ids} · RECOVERED`,`${item.title} · 已恢复`,`<div class="success-state"><i>✓</i><h3>已回到唯一合法状态</h3><p>迟到响应和重复请求不会重复应用；受影响的金币、库存、席位或账号状态已按权威快照刷新。</p></div><div class="modal-actions"><button class="btn primary" data-action="close-modal">完成</button></div>`,{type:'state-success'});});}
  function openMergePreview(){state.mergePreview={token:`MP-${Date.now()}`,expiresAt:Date.now()+300000};openModal('账号合并 · PREVIEW','确认合并结果',`<div class="merge-compare"><article><p class="eyebrow">当前账号</p><h3>${state.account.name} · #${state.account.id}</h3><span>修为 ${state.account.cultivation.toLocaleString()}</span><span>设备 ${state.account.sessions.length}</span></article><i>合并</i><article><p class="eyebrow">已占用身份</p><h3>云游客 · #2A91</h3><span>修为 9,760</span><span>图鉴状态逐项取高</span></article></div><div class="merge-result"><span><b>修为</b><small>取较高值，不相加 → ${state.account.cultivation.toLocaleString()}</small></span><span><b>图鉴</b><small>逐项取LOCKED/SEEN/USED/MASTERED中的较高状态</small></span><span><b>权益/外观</b><small>取并集，退款权益撤销优先</small></span><span><b>战报</b><small>按match_id去重保留最近20局</small></span><label><b>昵称冲突</b><select id="merge-name"><option value="current">保留“${state.account.name}”</option><option value="source">保留“云游客”</option></select></label></div><div class="notice">预览令牌5分钟有效；提交前不会覆盖任何账号数据。</div><div class="modal-actions"><button class="btn primary" data-action="commit-merge">确认合并</button><button class="btn ghost" data-action="close-modal">取消并保留两个账号</button></div>`,{type:'merge-preview'});}
  function commitMerge(){if(!state.mergePreview||Date.now()>state.mergePreview.expiresAt)return toast('合并预览已过期，请重新预览');const nameChoice=$('#merge-name')?.value;authority('ACCOUNT_MERGE_COMMIT',null,()=>({merged_account_id:state.account.id,merge_receipt_id:`MR-${Date.now()}`})).then(result=>{if(nameChoice==='source')state.account.name='云游客';state.mergePreview=null;openModal('账号合并 · COMMITTED','合并完成',`<div class="success-state"><i>✓</i><h3>回执 ${result.merge_receipt_id}</h3><p>修为取较高值、图鉴逐项取高、权益与外观取并集、战报去重保留最近20局。</p></div><div class="modal-actions"><button class="btn primary" data-action="binding-finish">完成</button></div>`,{type:'merge-success'});});}
  function openAimDataset(kind){ensureBattle();state.ui.aimSelection=[];const configs={aim:['精确瞄准','等待合法目标','拖动选择方向/落点；墙体后区域以纹理+文字标记非法。'], 'dual-target':['双目标选择器 · 3秒','等待目标A','选定A后必须在3秒内选择B；任一目标失效会清空。'],trap:['陷阱选择器','等待陷阱目标','短按引爆最近合法陷阱，长按列出编号、方向和状态。']},v=configs[kind],bCopy=kind==='dual-target'?'18m · 可选':'墙体阻挡';openModal(`J-01—J-16 · ${kind.toUpperCase()}`,v[0],`<div class="aim-dataset ${kind}"><div class="aim-path"></div><i class="aim-origin">你</i><button class="aim-target a" data-action="select-aim-target" data-target="A" data-kind="${kind}">A<small>12m · 可选</small></button><button class="aim-target b" data-action="select-aim-target" data-target="B" data-kind="${kind}">B<small>${bCopy}</small></button><span class="aim-range"></span><div class="aim-cancel">取消</div></div><div class="map-status"><span><b id="aim-selection-state">${v[1]}</b><small>${v[2]}</small></span><span><b>服务端未提交</b><small>取消/非法均不进入CD</small></span><span><b>双端同求解器</b><small>手机拖动 · PC按住0.22秒</small></span></div><div class="modal-actions"><button class="btn primary" data-action="aim-commit" data-kind="${kind}" disabled>提交合法预演</button><button class="btn ghost" data-action="close-modal">取消瞄准</button></div>`,{type:'aim',kind});}
