  function openLootHeap(page=0){const all=[...state.content.equipment.slice(0,16).map(item=>({item,type:'equipment'})),...state.content.passives.slice(0,4).map(item=>({item,type:'passive'})),...state.content.actives.filter(x=>x.类型==='通用').slice(0,4).map(item=>({item,type:'active'}))].sort((a,b)=>qualityRank(b.item)-qualityRank(a.item)||a.type.localeCompare(b.type)||a.item.ID.localeCompare(b.item.ID)),items=all.slice(page*12,page*12+12);openWorldSheet('长按交互 · K-01—K-27',`附近遗宝 · 第${page+1}/2页`,`<div class="interaction-warning">12项/页 · 装备按金→紫→蓝→白稳定排列。当前项被抢会把焦点移到下一项；光柱只代表堆内最高品质，不代表归属。</div><div class="loot-grid">${items.map((x,i)=>{const rarity=rarityClass(x.item,x.type),quality=equipmentQuality(x.item);return `<button class="${rarity}" data-action="loot-item" data-type="${x.type}" data-id="${x.item.ID}" data-index="${i}"><span class="item-art ${rarity}"><img src="${itemIcon(x.type,x.item.ID)}"></span><span><b>${esc(x.item.名称)}</b><small>${quality?`${quality.rank} ${quality.label}`:'公开地面物'} · ${i===3?'圈外销毁 00:42':'安全区内不自然过期'}</small></span>${quality?qualityBadge(x.item,{compact:true}):''}</button>`;}).join('')}</div><div class="world-sheet-actions"><button class="btn secondary" data-action="loot-page" data-page="${page-1}" ${page===0?'disabled':''}>上一页</button><button class="btn secondary" data-action="loot-page" data-page="${page+1}" ${page===1?'disabled':''}>下一页</button><button class="btn ghost" data-action="close-world-sheet">关闭</button></div>`,{type:'pickup',mode:'service',page});}
