  async function openSourceAudit(module='FRONT',page=0){if(!state.sourceAudit&&location.protocol!=='file:'){openWorldSheet('真源逐字段审计','正在载入验收数据','<div class="loading-card"><i></i><b>正在按需读取审计包</b><small>该资源不会再阻塞玩家启动。</small></div>',{type:'service',mode:'service'});try{const response=await fetch('source-visual-audit.json',{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);state.sourceAudit=await response.json();}catch(error){return openWorldSheet('真源逐字段审计','验收数据载入失败',`<div class="interaction-warning danger">${esc(error.message)} · 可返回战场重试，不影响对局。</div>`,{type:'service',mode:'service'});}}const audit=state.sourceAudit;if(!audit)return openWorldSheet('真源逐字段审计','审计数据尚未载入','<div class="interaction-warning danger">独立HTML缺少嵌入审计数据；请重新生成完整交付文件。</div>',{type:'service',mode:'service'});const summary=audit.summary,mod=audit.modules.find(x=>x.key===module)||audit.modules[0],missing=audit.fields.filter(x=>x.module===mod.key&&x.status==='MISSING_EVIDENCE'),allRows=missing.length?missing:audit.fields.filter(x=>x.module===mod.key),pageSize=80,pageCount=Math.max(1,Math.ceil(allRows.length/pageSize)),safePage=clamp(Number(page)||0,0,pageCount-1),rows=allRows.slice(safePage*pageSize,(safePage+1)*pageSize);openWorldSheet(`真源SHA ${summary.sourceSha256.slice(0,12)} · 精确值消费审计`,`模块 ${mod.key} · ${mod.sections.join(' / ')}`,`<div class="audit-overview"><b>${summary.auditedFields.toLocaleString()}字段逐一登记 · ${summary.exactValueBindings.toLocaleString()}精确值绑定 · 当前缺证据 ${summary.missing.toLocaleString()}</b><span>本模块 ${mod.total}字段 · 明确验证 ${mod.verified||0} · 工程隔离 ${mod.engineOnly||0} · 缺失 ${mod.missing} · 合同 ${mod.contracts.join(' / ')}</span></div><div class="audit-module-tabs">${audit.modules.map(x=>`<button class="${x.key===mod.key?'active':''}" data-action="source-audit-module" data-id="${x.key}" data-index="0">${x.key}<small>${x.missing?'缺'+x.missing:'✓'}</small></button>`).join('')}</div><div class="audit-overview"><b>本模块第 ${safePage+1}/${pageCount} 页</b><span>显示 ${safePage*pageSize+1}–${Math.min((safePage+1)*pageSize,allRows.length)} / ${allRows.length}；逐页可遍历，不截断。</span></div><div class="source-field-list">${rows.map(x=>`<article class="${x.status==='MISSING_EVIDENCE'?'missing':''}"><code>${x.id}</code><span><b>${esc(x.header)} · ${esc(x.rowKey)}</b><small>${esc(x.value)} · ${esc(x.dataPath)} · ${x.valueBindingVerified?'精确值PASS':'精确值FAIL'} · 行SHA ${x.sourceRowSha256.slice(0,12)}</small></span><em>${x.status}</em></article>`).join('')}</div><div class="world-sheet-actions">${safePage>0?`<button class="btn secondary" data-action="source-audit-module" data-id="${mod.key}" data-index="${safePage-1}">上一页</button>`:''}${safePage<pageCount-1?`<button class="btn secondary" data-action="source-audit-module" data-id="${mod.key}" data-index="${safePage+1}">下一页</button>`:''}<button class="btn secondary" data-action="ui-event-ledger">查看运行时UI事件</button><button class="btn ghost" data-action="close-world-sheet">返回战场</button></div>`,{type:'service',mode:'service',kind:'source-audit',module:mod.key,page:safePage});}
  function openUIEventLedger(){const rows=[...state.uiEventLog].reverse().slice(0,100);openWorldSheet('运行时视觉反馈证据','UI事件账本',`<div class="audit-overview"><b>${state.uiEventLog.length}条真实交互事件</b><span>每条均来自当前HTML实际状态变化；不是静态勾选。事件类型：${Object.values(UI_EVENT_TYPES).join(' / ')}</span></div><div class="source-field-list">${rows.length?rows.map(x=>`<article><code>${x.type}</code><span><b>${x.id}</b><small>${esc(JSON.stringify(x.payload))}</small></span><em>${x.at==null?'局外':padTime(x.at)}</em></article>`).join(''):'<article><span><b>暂无事件</b><small>执行开箱、拾取、买卖、换英雄、伤害或重连后会在这里留下证据。</small></span></article>'}</div><div class="world-sheet-actions"><button class="btn secondary" data-action="source-audit">返回真源审计</button><button class="btn ghost" data-action="close-world-sheet">关闭</button></div>`,{type:'service',mode:'service',kind:'ui-events'});}

  function qaPassiveScenario(id){if(!state.ui.qaEnabled)return;ensureBattle();const item=state.maps.passive.get(id);if(!item)return toast(`真源被动不存在：${id}`);state.match.passives=[{item,level:5},null,null,null];state.match.passiveRuntime=null;const target=state.sim.actors.find(x=>x.hp>0)||state.sim.actors[0],pve=state.pve.entities.find(x=>x.hp>0);if(target){target.x=state.sim.player.x+2;target.y=state.sim.player.y;target.hp=100;target.maxHp=100;target.gold=2000;target.lives=3;target.state='roam';}
    if(/^B(0[1-9]|1[0-4]|18|25|26|29|31|36|43|44)$/.test(id)&&target){for(let i=0;i<35;i++){const prepared=passiveBasicPrepare(target,state.match.attack);passiveBasicAfter(target,prepared.damage,prepared.crit);}}
    else if(/^B(15|16|17|19|20|22|23|24|27|38)$/.test(id)){state.match.hp=Math.max(200,state.match.maxHp);for(let i=0;i<30;i++){const incoming=passiveIncoming(40,'player');if(!passiveLethal(incoming,'player'))passiveAfterIncoming(incoming,'player');}}
    else if(/^B(21|28|30|34|39)$/.test(id)){state.match.pvpAge=20;state.match.elapsed=120;state.sim.moveVector={x:1,y:0};for(let i=0;i<12;i++)tickPassiveRuntime(1);state.sim.moveVector={x:0,y:0};}
    else if(/^B(32|33|40|42)$/.test(id)){const killTarget=id==='B42'?{...target,bounty:{payout:1500}}:{killType:'ORDINARY_MONSTER',x:pve?.x||state.sim.player.x+2,y:pve?.y||state.sim.player.y};if(id==='B33'){let chest=null;for(let i=0;i<25&&!chest;i++){state.match.kills++;chest=tryB33ChestDrop('ORDINARY_MONSTER',killTarget,false);}passiveLog('B33',chest?'CHEST_SPAWN':'ROLL_SERIES',{copy:chest?`怪物击杀生成宝箱 ${chest.instanceId}`:'连续25次确定性测试未生成宝箱'});}else passiveKill(killTarget,id==='B42'?'player':'monster',id==='B42');}
    else if(id==='B35')passiveLog('B35','QA_ECONOMY',{copy:'请在商店出售或拾取一次物品验证金额'});
    else if(id==='B37'){qaSpawnSummonArchetype('WOLF_SPIRIT',1);const summon=state.sim.summons.find(x=>x.sourceSkill==='B12');if(summon)damageSummon(summon.id,Infinity,'HOSTILE_PLAYER_DAMAGE','QA_PLAYER');}
    else if(id==='B41')passiveOwnerTrueDeath(target?.id||'P02','player');
    renderBuild();renderBattleHUD();updateLiveSimulationUI(false);const rows=passiveRuntime().ledger.filter(x=>x.id===id).slice(-12);openWorldSheet('表125被动运行时QA',`${id} · ${item.名称}`,`<div class="notice">已装备Lv.5并运行真实事件场景；下列为本次状态账本，不是静态说明。</div><div class="interaction-log">${rows.length?rows.map(x=>`<p><b>${esc(x.event)}</b><span>${x.at}s · ${esc(x.copy||JSON.stringify(x))}</span></p>`).join(''):'<p><b>等待条件</b><span>该机制需要匹配其严格触发条件；可继续在战场完成事件。</span></p>'}</div><div class="interaction-facts"><span><b>${state.match.hp}/${state.match.maxHp}</b><small>生命</small></span><span><b>${state.match.shield}</b><small>护盾</small></span><span><b>${state.match.gold}</b><small>金币</small></span><span><b>${state.match.activeCooldown}</b><small>主动CD</small></span></div><div class="world-sheet-actions"><button class="btn ghost" data-action="close-world-sheet">返回战场</button></div>`,{type:'service',mode:'service',kind:'passive-qa',passiveId:id});}
