  function openDragonGallery(){const states=['idle','move','attack','cast'],directions=['front','back','left','right','up-left','up-right','down-left','down-right'],labels={idle:'待机',move:'移动',attack:'攻击',cast:'施法',front:'正面',back:'背面',left:'左侧',right:'右侧','up-left':'左上','up-right':'右上','down-left':'左下','down-right':'右下'};openWorldSheet('龙王序列帧总览','4状态 × 8朝向 × 每组10帧',`<div class="dragon-animation-gallery">${states.flatMap(stateName=>directions.map(direction=>`<button data-action="qa-dragon-animation" data-state="${stateName}" data-direction="${direction}"><span class="dragon-qa-sequence" style="--dragon-duration:${DRAGON_ANIM_DURATION[stateName]}ms"><img src="${assetArt(`../assets/monsters/dragon-sprites/dragon-${stateName}-${direction}.webp`)}" alt=""></span><b>${labels[stateName]} · ${labels[direction]}</b><small>10帧 / ${DRAGON_ANIM_DURATION[stateName]}ms</small></button>`)).join('')}</div><div class="world-sheet-actions"><button class="btn ghost" data-action="close-world-sheet">返回战场</button></div>`,{type:'service',mode:'service',kind:'dragon-animation'});}
