  function qaStaticWallPair(){const walls=validCollisionWalls(state.worldSource).sort((a,b)=>Number(String(a.category).toUpperCase()==='BOUND')-Number(String(b.category).toUpperCase()==='BOUND'));for(const wall of walls)for(let i=0;i<wall.polygon.length;i++){const a=wall.polygon[i],b=wall.polygon[(i+1)%wall.polygon.length],mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2,dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy)||1,n={x:-dy/len,y:dx/len};for(const offset of [1.5,2,3,4,6,8,12]){const p1={x:mx+n.x*offset,y:my+n.y*offset},p2={x:mx-n.x*offset,y:my-n.y*offset};if(runtimePointIsClear(p1,{includeDynamic:false,clearance:.5})&&runtimePointIsClear(p2,{includeDynamic:false,clearance:.5})&&segmentCrossesPolygon(p1,p2,wall.polygon))return{wall,p1,p2};}}return null;}
